DG.put("ath-pakhyaan-charitr-likhyate/209",{"n":209,"title":null,"title_roman":null,"page":1833,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1833,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":1833,"lines":[{"gurmukhi":"ਧਾਰਾ ਨਗਰੀ ਕੋ ਰਹੈ ਭਰਥਰਿ ਰਾਵ ਸੁਜਾਨ।","roman":"Dhaaraa nagree ko rahai bharathri raav sujaan |","meaning_en":"In the city of Dhara there lived the wise king Bharthari,","page":1833,"meaning_status":"draft"},{"gurmukhi":"ਦੋ ਦ੍ਵਾਦਸ ਬਿਦ੍ਯਾ ਨਿਪੁਨ ਸੂਰਬੀਰ ਬਲਵਾਨ। ੧।","roman":"Do dvaadas bidyaa nipun soorbeer balvaan | 1 |","meaning_en":"skilled in the fourteen sciences, a brave and mighty warrior.","page":1833,"meaning_status":"draft","note":"ਦੋ ਦ੍ਵਾਦਸ: 'two and twelve', read as the fourteen branches of learning; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1835,"meaning_status":"draft"},{"type":"verse","number":[2],"number_text":"੨।","page":1835,"lines":[{"gurmukhi":"ਭਾਨ ਮਤੀ ਤਾ ਕੇ ਬਰ ਨਾਰੀ। ਪਿੰਗੁਲ ਦੇਇ ਪ੍ਰਾਨਨਿ ਤੇ ਪ੍ਯਾਰੀ।","roman":"Bhaan matee taa ke bar naaree | pingul dei praanni te pyaaree |","meaning_en":"Bhan Mati was his excellent wife, and Pingula was dearer to him than life.","page":1835,"meaning_status":"draft","note":"ਪਿੰਗੁਲ ਦੇਇ: printed 'Pingul Dei' here; the same queen as Pingula (also printed Pingulamati). Two queens are named, Bhan Mati and Pingula."},{"gurmukhi":"ਅਪ੍ਰਮਾਨ ਭਾ ਰਾਨੀ ਸੋਹੈ। ਦੇਵ ਅਦੇਵ ਸੁਤਾ ਢਿਗ ਕੋ ਹੈ। ੨।","roman":"Apramaan bhaa raanee sohai | dev adev sutaa dhig ko hai | 2 |","meaning_en":"The queen shone with measureless radiance; what were the daughters of gods and demons beside her?","page":1835,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1835,"meaning_status":"draft"},{"type":"verse","number":[3],"number_text":"੩।","page":1835,"lines":[{"gurmukhi":"ਭਾਨ ਮਤੀ ਕੀ ਅਧਿਕ ਛਬਿ ਜਲ ਥਲ ਰਹੀ ਸਮਾਇ।","roman":"Bhaan matee kee adhik chhabi jal thal rahee samaai |","meaning_en":"The great beauty of Bhan Mati filled water and land;","page":1835,"meaning_status":"draft"},{"gurmukhi":"ਦੇਵ ਦਿਵਾਨੇ ਲਖਿ ਭਏ ਦਾਨਵ ਗਏ ਬਿਕਾਇ। ੩।","roman":"Dev divaane lakhi bhae daanav gae bikaai | 3 |","meaning_en":"the gods went mad at the sight of it, and the demons were sold into her service.","page":1835,"meaning_status":"draft","note":"ਗਏ ਬਿਕਾਇ: 'were sold', i.e. became her slaves."}]},{"type":"verse","number":[4],"number_text":"੪।","page":1835,"lines":[{"gurmukhi":"ਔਰ ਪਿੰਗੁਲਾਮਤੀ ਕੀ ਸੋਭਾ ਲਖੀ ਅਪਾਰ।","roman":"Aur pingulaamtee kee sobhaa lakhee apaar |","meaning_en":"And the loveliness of Pingula was seen to be boundless;","page":1835,"meaning_status":"draft","note":"ਪਿੰਗੁਲਾਮਤੀ: printed 'Pingulamati' here."},{"gurmukhi":"ਗੜਿ ਚਤੁਰਾਨਨ ਤਵਨ ਸਮ ਔਰ ਨ ਸਕਿਯੋ ਸੁਧਾਰ। ੪।","roman":"Gari chaturaanan tavan sam aur na sakiyo sudhaar | 4 |","meaning_en":"having fashioned her, the four-faced one could not shape another like her.","page":1835,"meaning_status":"draft","note":"ਚਤੁਰਾਨਨ: Brahma."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1835,"meaning_status":"draft"},{"type":"verse","number":[5],"number_text":"੫।","page":1835,"lines":[{"gurmukhi":"ਏਕ ਦਿਵਸ ਨ੍ਰਿਪ ਗਯੋ ਸਿਕਾਰਾ। ਚਿਤ ਭੀਤਰ ਇਹ ਭਾਤਿ ਬਿਚਾਰਾ।","roman":"Ek divas nrip gayo sikaaraa | chit bheetar ih bhaati bichaaraa |","meaning_en":"One day the king went hunting, and thought in this way in his mind;","page":1835,"meaning_status":"draft"},{"gurmukhi":"ਬਸਤ੍ਰ ਬੋਰਿ ਸ੍ਰੋਨਤਹਿ ਪਠਾਏ। ਕਹਿਯੋ ਸਿੰਘ ਭਰਥਰ ਹਰਿ ਘਾਏ। ੫।","roman":"Basatr bori sronathi pathaae | kahiyo singh bharthar hari ghaae | 5 |","meaning_en":"he dipped his clothes in blood and sent them, saying, 'A lion has killed Bharthari.'","page":1835,"meaning_status":"draft","note":"ਭਰਥਰ ਹਰਿ: the name Bhartrihari, printed in two words."}]},{"type":"verse","number":[6],"number_text":"੬।","page":1835,"lines":[{"gurmukhi":"ਬਸਤ੍ਰ ਭ੍ਰਿਤ ਲੈ ਸਦਨ ਸਿਧਾਰਿਯੋ। ਉਚਰਿਯੋ ਆਜੁ ਸਿੰਘ ਨ੍ਰਿਪ ਮਾਰਿਯੋ।","roman":"Basatr bhrit lai sadan sidhaariyo | uchriyo aaju singh nrip maariyo |","meaning_en":"The servant took the clothes and went to the palace, and declared, 'Today a lion has killed the king.'","page":1835,"meaning_status":"draft"},{"gurmukhi":"ਰਾਨੀ ਉਦਿਤ ਜਰਨ ਕੌ ਭਈ। ਹਾਇ ਉਚਰਿ ਪਿੰਗਲ ਮਰਿ ਗਈ। ੬।","roman":"Raanee udit jaran kau bhaee | haai uchri pingal mari gaee | 6 |","meaning_en":"The queen made ready to burn herself; Pingula cried 'Alas!' and died.","page":1835,"meaning_status":"draft","note":"'The queen' is taken as Bhan Mati; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1835,"meaning_status":"draft"},{"type":"verse","number":[7],"number_text":"੭।","page":1835,"lines":[{"gurmukhi":"ਤ੍ਰਿਯਾ ਨ ਤਵਨ ਸਰਾਹੀਯਹਿ ਕਰਤ ਅਗਨਿ ਮੈ ਪਯਾਨ।","roman":"Triyaa na tavan saraaheeyhi karat agni mai payaan |","meaning_en":"That woman is not the one to be praised who makes her way into the fire;","page":1835,"meaning_status":"draft"},{"gurmukhi":"ਧੰਨ੍ਯ ਧੰਨ੍ਯ ਅਬਲਾ ਤੇਈ ਬਧਤ ਬਿਰਹ ਕੇ ਬਾਨ। ੭।","roman":"Dhanny dhanny ablaa te'ee badhat birah ke baan | 7 |","meaning_en":"blessed, blessed are those women who are slain by the arrows of separation.","page":1835,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1835,"meaning_status":"draft"},{"type":"verse","number":[8],"number_text":"੮।","page":1835,"lines":[{"gurmukhi":"ਖੇਲਿ ਅਖੇਟਕ ਜਬ ਭਰਥਰਿ ਘਰਿ ਆਇਯੋ।","roman":"Kheli akhetak jab bharathri ghari aaiyo |","meaning_en":"When Bharthari came home after the hunt,","page":1835,"meaning_status":"draft"},{"gurmukhi":"ਹਾਇ ਕਰਤ ਪਿੰਗੁਲਾ ਮਰੀ ਸੁਨਿ ਪਾਇਯੋ।","roman":"Haai karat pingulaa maree suni paaiyo |","meaning_en":"he heard that Pingula had died crying 'Alas!'","page":1835,"meaning_status":"draft"},{"gurmukhi":"ਡਾਰਿ ਡਾਰਿ ਸਿਰ ਧੂਰਿ ਹਾਇ ਰਾਜਾ ਕਹੈ।","roman":"Daari daari sir dhoori haai raajaa kahai |","meaning_en":"Throwing dust again and again on his head, the king cried 'Alas!","page":1835,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਪਠੈ ਬਸਤ੍ਰ ਜਿਹ ਸਮੈ ਸਮੋ ਸੌ ਨ ਲਹੈ। ੮।","roman":"Ho pathai basatr jih samai samo sau na lahai | 8 |","meaning_en":"The moment in which I sent the clothes - that moment I cannot get back.'","page":1835,"meaning_status":"draft","note":"ਸਮੋ ਸੌ ਨ ਲਹੈ: 'that time is not found'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1835,"meaning_status":"draft"},{"type":"verse","number":[9],"number_text":"੯।","page":1835,"lines":[{"gurmukhi":"ਕੈ ਮੈ ਆਜੁ ਕਟਾਰੀ ਮਾਰੌ। ਹ੍ਵੈ ਜੋਗੀ ਸਭ ਹੀ ਘਰ ਜਾਰੌ।","roman":"Kai mai aaju kataaree maarau | hvai jogee sabh hee ghar jaarau |","meaning_en":"'Either I will strike myself with a dagger today, or become a yogi and burn the whole house.","page":1835,"meaning_status":"draft"},{"gurmukhi":"ਧ੍ਰਿਗ ਮੇਰੋ ਜਿਯਬੋ ਜਗ ਮਾਹੀ। ਜਾ ਕੇ ਨਾਰਿ ਪਿੰਗੁਲਾ ਨਾਹੀ। ੯।","roman":"Dhrig mero jiybo jag maahee | jaa ke naari pingulaa naahee | 9 |","meaning_en":"Cursed is my living in the world, who have not my wife Pingula.'","page":1835,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1835,"meaning_status":"draft"},{"type":"verse","number":[10],"number_text":"੧੦।","page":1835,"lines":[{"gurmukhi":"ਜੋ ਭੂਖਨ ਬਹੁ ਮੋਲ ਕੇ ਅੰਗਨ ਅਧਿਕ ਸੁਹਾਹਿ।","roman":"Jo bhookhan bahu mol ke angan adhik suhaahi |","meaning_en":"The ornaments of great price that looked so fine upon the limbs","page":1835,"meaning_status":"draft"},{"gurmukhi":"ਤੇ ਅਬ ਨਾਗਨਿ ਸੇ ਭਏ ਕਾਟਿ ਕਾਟਿ ਤਨ ਖਾਹਿ। ੧੦।","roman":"Te ab naagni se bhae kaati kaati tan khaahi | 10 |","meaning_en":"have now become like she-snakes; they bite and eat the body.","page":1835,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1835,"meaning_status":"draft"},{"type":"verse","number":[11],"number_text":"੧੧।","page":1835,"lines":[{"gurmukhi":"ਬਾਂਕ ਸੀ ਬੀਨ ਸਿੰਗਾਰ ਅੰਗਾਰ ਸੇ ਤਾਲ ਮ੍ਰਿਦੰਗ ਕ੍ਰਿਪਾਨ ਕਟਾਰੇ।","roman":"Baank see been singaar angaar se taal mridang kripaan kataare |","meaning_en":"The veena is like a curved dagger, adornments are like burning coals, the cymbals and drum are swords and daggers;","page":1835,"meaning_status":"draft","note":"ਬਾਂਕ: a curved dagger. Verses 11-13 list pleasant things that have turned painful; many comparisons are compressed and uncertain."},{"gurmukhi":"ਜ੍ਵਾਲ ਸੀ ਜੌਨਿ ਜੁਡਾਈ ਸੀ ਜੇਬ ਸਖੀ ਘਨਸਾਰ ਕਿਸਾਰ ਕੇ ਆਰੇ।","roman":"Jvaal see jauni judaaee see jeb sakhee ghansaar kisaar ke aare |","meaning_en":"the moonlight is like flame, beauty like a shivering fever, O friend, and camphor like the teeth of a saw;","page":1835,"meaning_status":"draft","note":"ਜੁਡਾਈ: read as 'ague, cold fever'; ਜੇਬ: 'beauty, grace'; ਕਿਸਾਰ ਕੇ ਆਰੇ: read as 'saws'; all uncertain."},{"gurmukhi":"ਰੋਗ ਸੋ ਰਾਗ ਬਿਰਾਗ ਸੋ ਬੋਲ ਬਬਾਰਿਦ ਬੂੰਦਨ ਬਾਨ ਬਿਸਾਰੇ।","roman":"Rog so raag biraag so bol babaarid boondan baan bisaare |","meaning_en":"music is like sickness, speech like grief, and the drops from the clouds are poisoned arrows;","page":1837,"meaning_status":"draft","note":"ਬਿਰਾਗ: here 'sorrow'; ਬਬਾਰਿਦ: read as ਬਾਰਿਦ 'cloud'; ਬਿਸਾਰੇ: 'poisoned'; uncertain."},{"gurmukhi":"ਬਾਨ ਸੇ ਬੈਨ ਭਾਲਾ ਜੈਸੇ ਭੂਖਨ ਹਾਰਨ ਹੋਹਿ ਭੁਜੰਗਨ ਕਾਰੇ। ੧੧।","roman":"Baan se bain bhaalaa jaise bhookhan haaran hohi bhujangan kaare | 11 |","meaning_en":"words are like arrows, ornaments like spears, and necklaces become black serpents.","page":1837,"meaning_status":"draft"}]},{"type":"verse","number":[12],"number_text":"੧੨।","page":1837,"lines":[{"gurmukhi":"ਬਾਂਕ ਸੇ ਬੈਨ ਬ੍ਰਿਲਾਪ ਸੇ ਬਾਰਨ ਬ੍ਯਾਧ ਸੀ ਬਾਸ ਬਿਯਾਰ ਬਹੀ ਰੀ।","roman":"Baank se bain brilaap se baaran byaadh see baas biyaar bahee ree |","meaning_en":"Words are like daggers, songs like lamentation, and the fragrant breeze blows like a disease, O friend;","page":1837,"meaning_status":"draft","note":"ਬਾਰਨ: unclear; read loosely as 'songs/sounds'; ਬ੍ਯਾਧ: 'disease' (or 'hunter'); uncertain."},{"gurmukhi":"ਕਾਕ ਸੀ ਕੋਕਿਲ ਕੂਕ ਕਰਾਲ ਮ੍ਰਿਨਾਲ ਕਿ ਬ੍ਯਾਲ ਘਰੀ ਕਿ ਛੁਰੀ ਰੀ।","roman":"Kaak see kokil kook karaal mrinaal ki byaal gharee ki chhuree ree |","meaning_en":"the cuckoo's call is dreadful, like a crow's; is it a lotus-stalk or a snake, an hour or a knife, O friend?","page":1837,"meaning_status":"draft","note":"ਘਰੀ: 'hour' (a ghari); uncertain."},{"gurmukhi":"ਭਾਰ ਸੀ ਭੌਨ ਭਯਾਨਕ ਭੂਖਨ ਜੌਨ ਕੀ ਜ੍ਵਾਲ ਸੌ ਜਾਤ ਜਰੀ ਰੀ।","roman":"Bhaar see bhaun bhayaanak bhookhan jaun kee jvaal sau jaat jaree ree |","meaning_en":"The house is like a furnace, the ornaments are fearful, and one is burned by the flame of the moonlight, O friend;","page":1837,"meaning_status":"draft","note":"ਭਾਰ: read as ਭਾੜ, a parching-oven; ਜੌਨ: moonlight."},{"gurmukhi":"ਬਾਨ ਸੀ ਬੀਨ ਬਿਨਾ ਉਹਿ ਬਾਲ ਬਸੰਤ ਕੋ ਅੰਤਕਿ ਅੰਤ ਸਖੀ ਰੀ। ੧੨।","roman":"Baan see been binaa uhi baal basant ko antki ant sakhee ree | 12 |","meaning_en":"the veena is like an arrow; without that lady, O friend, spring is the very end of ends.","page":1837,"meaning_status":"draft","note":"ਅੰਤਕਿ ਅੰਤ: 'the death of death' or 'death itself'; uncertain."}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":1837,"lines":[{"gurmukhi":"ਬੈਰੀ ਸੀ ਬ੍ਯਾਰ ਬ੍ਰਿਲਾਪ ਸੌ ਬੋਲ ਬਬਾਨ ਸੀ ਬੀਨ ਬਜੰਤ ਬਿਥਾਰੇ।","roman":"Bairee see byaar brilaap sau bol babaan see been bajant bithaare |","meaning_en":"The breeze is like an enemy, speech like lamentation, and the sounding veena spreads pain like an arrow;","page":1837,"meaning_status":"draft","note":"ਬਬਾਨ: read as ਬਾਨ 'arrow'; ਬਿਥਾਰੇ: 'spreads' or 'painful'; uncertain."},{"gurmukhi":"ਜੰਗ ਸੇ ਜੰਗ ਮੁਚੰਗ ਦੁਖੰਗ ਅਨੰਗ ਕਿ ਅੰਕਸੁ ਆਕ ਕਿਆਰੇ।","roman":"Jang se jang muchang dukhang anang ki anksu aak kiaare |","meaning_en":"the bells are like war, the muchang hurts the limbs, and the flower-beds are the love-god's goad or beds of bitter aak;","page":1837,"meaning_status":"draft","note":"ਜੰਗ ਸੇ ਜੰਗ: 'jang (bells) like jang (war)'; ਦੁਖੰਗ: 'paining the body'; ਆਕ: the bitter milkweed; uncertain."},{"gurmukhi":"ਚਾਂਦਨੀ ਚੰਦ ਚਿਤਾ ਚਹੂੰ ਓਰ ਸੁ ਕੋਕਿਲਾ ਕੂਕ ਕਿ ਹੂਕ ਸੀ ਮਾਰੇ।","roman":"Chaandnee chand chitaa chahoon or su kokilaa kook ki hook see maare |","meaning_en":"the light of the moon is a funeral pyre on all four sides, and the call of the cuckoo strikes like a stab of pain;","page":1837,"meaning_status":"draft","note":"ਹੂਕ: a pang."},{"gurmukhi":"ਭਾਰ ਸੇ ਭੌਨ ਭਯਾਨਕ ਭੂਖਨ ਫੂਲੇ ਨ ਫੂਲ ਫਨੀ ਫਨਿਯਾਰੇ। ੧੩।","roman":"Bhaar se bhaun bhayaanak bhookhan phoole na phool phanee phaniyaare | 13 |","meaning_en":"the house is like a furnace, the ornaments are fearful; these are not flowers in bloom but hooded serpents.","page":1837,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1837,"meaning_status":"draft"},{"type":"verse","number":[14],"number_text":"੧੪।","page":1837,"lines":[{"gurmukhi":"ਹੋ ਹਠਿ ਹਾਥ ਸਿੰਧੌਰਾ ਧਰਿ ਹੌ। ਪਿੰਗੁਲ ਹੇਤ ਅਗਨਿ ਮਹਿ ਜਰਿ ਹੌ।","roman":"Ho hathi haath sindhauraa dhari hau | pingul het agni mahi jari hau |","meaning_en":"'I will resolutely take the sindhaura in my hand, and burn in the fire for the sake of Pingula.","page":1837,"meaning_status":"draft","note":"ਸਿੰਧੌਰਾ: the vermilion-box (or coconut) held by one about to burn on a pyre. ਹੋ: here read as 'I' (ਹੌ) or the vocative; uncertain."},{"gurmukhi":"ਜੌ ਇਹ ਆਜੁ ਚੰਚਲਾ ਜੀਯੈ। ਤਬ ਭਰਥਰੀ ਪਾਨਿ ਕੌ ਪੀਯੈ। ੧੪।","roman":"Jau ih aaju chanchlaa jeeyai | tab bharathree paani kau peeyai | 14 |","meaning_en":"Only if this lady were to live today would Bharthari drink water.'","page":1837,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1837,"meaning_status":"draft"},{"type":"verse","number":[15],"number_text":"੧੫।","page":1837,"lines":[{"gurmukhi":"ਤਬ ਤਹ ਗੋਰਖਨਾਥ ਪਹੂੰਚ੍ਯੋ ਆਇ ਕੈ।","roman":"Tab tah gorakhnaath pahoonchyo aai kai |","meaning_en":"Then Gorakhnath arrived at that place;","page":1837,"meaning_status":"draft"},{"gurmukhi":"ਨ੍ਰਿਪ ਪ੍ਰਤਿ ਕਹਿਯੋ ਅਦੇਸੁ ਸੁ ਨਾਦ ਬਜਾਇ ਕੈ।","roman":"Nrip prati kahiyo adesu su naad bajaai kai |","meaning_en":"sounding his horn, he said 'Ades' to the king.","page":1837,"meaning_status":"draft","note":"ਅਦੇਸੁ: 'Ades', the yogis' greeting."},{"gurmukhi":"ਰਾਨੀ ਦਈ ਜਿਵਾਇ ਸਰੂਪ ਅਨੇਕ ਧਰਿ।","roman":"Raanee daee jivaai saroop anek dhari |","meaning_en":"He brought the queen back to life, making many forms of her:","page":1837,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸੁਨਹੋ ਭਰਥਰਿ ਰਾਵ ਲੇਹੁ ਗਹਿ ਏਕ ਕਰੁ। ੧੫।","roman":"Ho sunho bharathri raav lehu gahi ek karu | 15 |","meaning_en":"'Listen, King Bharthari: take hold of one of them by the hand.'","page":1837,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਭਰਥਰਿ ਬਾਚ","gurmukhi":"ਭਰਥਰਿ ਬਾਚ","roman":"Bharathri baach","meaning_en":"Bharthari said:","page":1837,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1837,"meaning_status":"draft"},{"type":"verse","number":[16],"number_text":"੧੬।","page":1837,"lines":[{"gurmukhi":"ਕਾਹ ਗਹੌ ਕੌਨੇ ਤਜੌ ਚਿਤ ਮੈ ਕਰੈ ਬਿਬੇਕ।","roman":"Kaah gahau kaune tajau chit mai karai bibek |","meaning_en":"'Which should I take and which leave? I weigh it in my mind;","page":1837,"meaning_status":"draft"},{"gurmukhi":"ਸਭੈ ਪਿੰਗੁਲਾ ਕੀ ਪ੍ਰਭਾ ਰਾਨੀ ਭਈ ਅਨੇਕ। ੧੬।","roman":"Sabhai pingulaa kee prabhaa raanee bhaee anek | 16 |","meaning_en":"all have the radiance of Pingula; the queen has become many.'","page":1837,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1837,"meaning_status":"draft"},{"type":"verse","number":[17],"number_text":"੧੭।","page":1837,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਗੋਰਖ ਨਾਥ ਤਹਾ ਤੇ ਜਾਤ ਭਯੋ।","roman":"Yau kahi gorakh naath tahaa te jaat bhayo |","meaning_en":"Having said this, Gorakhnath went away from there.","page":1837,"meaning_status":"draft","note":"'Having said this' is printed after Bharthari's words; translated as printed."},{"gurmukhi":"ਭਾਨ ਮਤੀ ਕੋ ਚਿਤ ਚੰਡਾਰ ਇਕ ਹਰ ਲਿਯੋ।","roman":"Bhaan matee ko chit chandaar ik har liyo |","meaning_en":"A chandal stole away the heart of Bhan Mati.","page":1837,"meaning_status":"draft","note":"ਚੰਡਾਰ: a chandal, a man of the lowest caste."},{"gurmukhi":"ਤਾ ਦਿਨ ਤੇ ਰਾਜਾ ਕੌ ਦਿਯੋ ਭੁਲਾਇ ਕੈ।","roman":"Taa din te raajaa kau diyo bhulaai kai |","meaning_en":"From that day she put the king out of her mind;","page":1837,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਰਾਨੀ ਨੀਚ ਕੇ ਰੂਪ ਰਹੀ ਉਰਝਾਇ ਕੈ। ੧੭।","roman":"Ho raanee neech ke roop rahee urjhaai kai | 17 |","meaning_en":"the queen remained entangled in the looks of the low-born man.","page":1837,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1839,"meaning_status":"draft"},{"type":"verse","number":[18],"number_text":"੧੮।","page":1839,"lines":[{"gurmukhi":"ਦੂਤਮਤੀ ਦਾਸੀ ਹੁਤੀ ਤਬ ਹੀ ਲਈ ਬੁਲਾਇ।","roman":"Dootamtee daasee hutee tab hee laee bulaai |","meaning_en":"There was a maid named Dut Mati; she called her at once,","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਪਠੈ ਦੇਤ ਭੀ ਨੀਚ ਸੌ ਪਰਮ ਪ੍ਰੀਤਿ ਉਪਜਾਇ। ੧੮।","roman":"Pathai det bhee neech sau param preeti upjaai | 18 |","meaning_en":"and sent her to the low-born man, great love having risen in her.","page":1839,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1839,"meaning_status":"draft"},{"type":"verse","number":[19],"number_text":"੧੯।","page":1839,"lines":[{"gurmukhi":"ਜਬ ਦੂਤੀ ਤਹ ਤੇ ਫਿਰਿ ਆਈ। ਯੌ ਪੂਛੌ ਰਾਨੀ ਤਿਹ ਜਾਈ।","roman":"Jab dootee tah te phiri aaee | yau poochhau raanee tih jaaee |","meaning_en":"When the go-between came back from there, the queen went and asked her this:","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਕਹੁ ਅਲਿ ਮੀਤ ਕਬੈ ਹ੍ਯਾ ਐ ਹੈ। ਹਮਰੇ ਚਿਤ ਕੋ ਤਾਪ ਮਿਟੈ ਹੈ। ੧੯।","roman":"Kahu ali meet kabai hyaa ai hai | hamre chit ko taap mitai hai | 19 |","meaning_en":"'Tell me, friend, when will my friend come here and take away the burning of my heart?","page":1839,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1839,"meaning_status":"draft"},{"type":"verse","number":[20],"number_text":"੨੦।","page":1839,"lines":[{"gurmukhi":"ਕਹੁ ਨ ਸਹਚਰੀ ਸਾਚੁ ਸਜਨੁ ਕਬ ਆਇ ਹੈ।","roman":"Kahu na sahachree saachu sajnu kab aai hai |","meaning_en":"Tell me truly, companion, when will my dear one come?","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਜੋਰ ਨੈਨ ਸੌ ਨੈਨ ਕਬੈ ਮੁਸਕਾਇ ਹੈ।","roman":"Jor nain sau nain kabai muskaai hai |","meaning_en":"When will he join his eyes with my eyes and smile?","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਲਪਟਿ ਲਪਟਿ ਕਰਿ ਜਾਉ ਲਲਾ ਸੌ ਤੌਨ ਛਿਨ।","roman":"Lapti lapti kari jaau lalaa sau taun chhin |","meaning_en":"In that moment I shall cling and cling to my darling.","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਹੋ ਸਖੀ ਮੁਹਿ ਮੀਤ ਕਬੈ ਹੈ ਕਵਨ ਦਿਨ। ੨੦।","roman":"Ho kaho sakhee muhi meet kabai hai kavan din | 20 |","meaning_en":"Tell me, friend: when, on what day, will my friend be here?","page":1839,"meaning_status":"draft"}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":1839,"lines":[{"gurmukhi":"ਬਾਰ ਬਾਰ ਗਜ ਮੁਤਿਯਨ ਗੁਹੌ ਬਨਾਇ ਕੈ।","roman":"Baar baar gaj mutiyan guhau banaai kai |","meaning_en":"I would string elephant-pearls in every single hair,","page":1839,"meaning_status":"draft","note":"ਬਾਰ ਬਾਰ: 'hair by hair' (or 'again and again'). ਗਜ ਮੁਤਿਯਨ: pearls said to come from an elephant's temple."},{"gurmukhi":"ਅਪਨੇ ਲਲਾ ਕੋ ਛਿਨ ਮੈ ਲੇਉ ਰਿਝਾਇ ਕੈ।","roman":"Apne lalaa ko chhin mai leu rijhaai kai |","meaning_en":"and in a moment win the delight of my darling.","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਟੂਕ ਟੂਕ ਤਨ ਹੋਇ ਨ ਮੇਰੋ ਨੈਕ ਮਨ।","roman":"Took took tan hoi na mero naik man |","meaning_en":"Though my body were cut to pieces, my mind would not turn in the least;","page":1839,"meaning_status":"draft","note":"ਨ ਮੇਰੋ: printed so; read as 'would not turn' (ਨ ਮੋਰੋ); uncertain."},{"gurmukhi":"ਹੋ ਕਾਸੀ ਕਰਵਤ ਲਿਯੋ ਪ੍ਰਿਯਾ ਕੀ ਪ੍ਰੀਤ ਤਨ। ੨੧।","roman":"Ho kaasee karvat liyo priyaa kee preet tan | 21 |","meaning_en":"for love of my dear one I would take the saw at Kashi upon my body.","page":1839,"meaning_status":"draft","note":"ਕਾਸੀ ਕਰਵਤ: the saw at Kashi, under which devotees were said to be cut in two. ਪ੍ਰਿਯਾ: printed in the feminine; the lover is meant."}]},{"type":"verse","number":[22],"number_text":"੨੨।","page":1839,"lines":[{"gurmukhi":"ਬਿਹਸਿ ਬਿਹਸਿ ਕਬ ਗਰੇ ਹਮਾਰੇ ਲਾਗਿ ਹੈ।","roman":"Bihsi bihsi kab gare hamaare laagi hai |","meaning_en":"When will he laugh and laugh and hold me round the neck?","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਹੀ ਸਭ ਹੀ ਸੋਕ ਹਮਾਰੇ ਭਾਗਿ ਹੈ।","roman":"Tab hee sabh hee sok hamaare bhaagi hai |","meaning_en":"Then at once all my sorrows will flee.","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਚਟਕ ਚਟਕ ਦੈ ਬਾਤੈ ਮਟਕਿ ਬਤਾਇ ਹੈ।","roman":"Chatak chatak dai baatai matki bataai hai |","meaning_en":"When he snaps his fingers and talks with playful gestures,","page":1839,"meaning_status":"draft","note":"ਚਟਕ ਚਟਕ ਦੈ: 'giving snap after snap'; uncertain."},{"gurmukhi":"ਹੋ ਤਾ ਦਿਨ ਸਖੀ ਸਹਿਤ ਹਮ ਬਲਿ ਬਲਿ ਜਾਇ ਹੈ। ੨੨।","roman":"Ho taa din sakhee sahit ham bali bali jaai hai | 22 |","meaning_en":"on that day, friend, I and you with me will be a sacrifice to him.","page":1839,"meaning_status":"draft","note":"ਸਖੀ ਸਹਿਤ: 'together with my friend'; uncertain."}]},{"type":"verse","number":[23],"number_text":"੨੩।","page":1839,"lines":[{"gurmukhi":"ਜੌ ਐਸੇ ਝਰਿ ਮਿਲੈ ਸਜਨ ਸਖਿ ਆਇ ਕੈ।","roman":"Jau aise jhari milai sajan sakhi aai kai |","meaning_en":"If my dear one comes and meets me so, O friend, in a rush,","page":1839,"meaning_status":"draft","note":"ਝਰਿ: read as 'in a shower, all at once'; uncertain."},{"gurmukhi":"ਮੋ ਮਨ ਕੌ ਲੈ ਤਬ ਹੀ ਜਾਇ ਚੁਰਾਇ ਕੈ।","roman":"Mo man kau lai tab hee jaai churaai kai |","meaning_en":"he will steal my heart away that very moment.","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਰਤਿ ਕਰੌ ਨ ਛੋਰੋ ਏਕ ਛਿਨ।","roman":"Bhaati bhaati rati karau na chhoro ek chhin |","meaning_en":"I shall make love in many ways and not let him go for a single instant;","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਬੀਤੈ ਮਾਸ ਪਚਾਸਨ ਜਾਨੌ ਏਕ ਦਿਨ। ੨੩।","roman":"Ho beetai maas pachaasan jaanau ek din | 23 |","meaning_en":"though fifty months should pass, I shall count them as one day.","page":1839,"meaning_status":"draft"}]},{"type":"verse","number":[24],"number_text":"੨੪।","page":1839,"lines":[{"gurmukhi":"ਮਚਕਿ ਮਚਕਿ ਕਬ ਕਹਿ ਹੈ ਬਚਨ ਬਨਾਇ ਕੈ।","roman":"Machki machki kab kahi hai bachan banaai kai |","meaning_en":"When will he sway and sway and speak well-turned words?","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਲਚਕਿ ਲਚਕਿ ਉਰ ਸਾਥ ਚਿਮਟਿ ਹੈ ਆਇ ਕੈ।","roman":"Lachki lachki ur saath chimti hai aai kai |","meaning_en":"When will he come, bending gracefully, and cling to my breast?","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਲਪਟਿ ਲਪਟਿ ਮੈ ਜਾਉ ਪ੍ਰਿਯ ਕੈ ਅੰਗ ਤਨ।","roman":"Lapti lapti mai jaau priy kai ang tan |","meaning_en":"I shall cling and cling to the limbs and body of my dear one,","page":1839,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਮੇਲ ਮੇਲ ਕਰਿ ਰਾਖੋ ਭੀਤਰ ਤਾਹਿ ਮਨ। ੨੪।","roman":"Ho mel mel kari raakho bheetar taahi man | 24 |","meaning_en":"and keep him joined and joined within my heart.'","page":1839,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1839,"meaning_status":"draft"},{"type":"verse","number":[25],"number_text":"੨੫।","page":1839,"lines":[{"gurmukhi":"ਖੰਜਨ ਹੂੰ ਨ ਬਦ੍ਯੋ ਕਛੁ ਕੈ ਕਰਿ ਕੰਜੁ ਕੁਰੰਗ ਕਹਾ ਕਰਿ ਡਾਰੇ।","roman":"Khanjan hoon na badyo kachhu kai kari kanju kurang kahaa kari daare |","meaning_en":"'They count the wagtail as nothing at all; to what have they brought the lotus and the deer?","page":1839,"meaning_status":"draft","note":"The queen praises the lover's eyes, comparing them with things eyes are usually likened to."},{"gurmukhi":"ਚਾਰੁ ਚਕੋਰ ਨ ਆਨੇ ਹ੍ਰਿਦੈ ਪਰ ਝੁੰਡ ਝਖੀਨਹੁ ਕੋ ਝਝਕਾਰੇ।","roman":"Chaaru chakor na aane hridai par jhund jhakheenhu ko jhajhkaare |","meaning_en":"They do not take the lovely chakor to heart, and they have scorned whole shoals of fish.","page":1839,"meaning_status":"draft","note":"ਝਝਕਾਰੇ: 'rebuffed'."},{"gurmukhi":"ਮੈਨ ਰਹਿਯੋ ਮੁਰਛਾਇ ਪ੍ਰਭਾ ਲਖਿ ਸਾਰਸ ਭੈ ਸਭ ਦਾਸ ਬਿਚਾਰੇ।","roman":"Main rahiyo murchhaai prabhaa lakhi saaras bhai sabh daas bichaare |","meaning_en":"The god of love lies in a swoon at the sight of their radiance; the lotuses have all become poor slaves.","page":1839,"meaning_status":"draft","note":"ਸਾਰਸ: 'lotus' (or 'crane'); uncertain."},{"gurmukhi":"ਅੰਤਕ ਸੋਚਨ ਧੀਰਜ ਮੋਚਨ ਲਾਲਚੀ ਲੋਚਨ ਲਾਲ ਤਿਹਾਰੇ। ੨੫।","roman":"Antak sochan dheeraj mochan laalchee lochan laal tihaare | 25 |","meaning_en":"Ending sorrow and taking away composure, your eyes, my darling, are greedy.'","page":1839,"meaning_status":"draft","note":"ਅੰਤਕ ਸੋਚਨ: 'bringing an end to cares' or 'deadly, causing care'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1841,"meaning_status":"draft"},{"type":"verse","number":[26],"number_text":"੨੬।","page":1841,"lines":[{"gurmukhi":"ਸੁਨਤ ਸਹਚਰੀ ਬਚਨ ਤਹਾ ਤੇ ਤਹ ਗਈ।","roman":"Sunat sahachree bachan tahaa te tah gaee |","meaning_en":"Hearing these words, the companion went from there to that place;","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਚਾਤੁਰਤਾ ਬਹੁ ਭਾਤਿ ਸਿਖਾਵਤ ਇਹ ਭਈ।","roman":"Chaaturtaa bahu bhaati sikhaavat ih bhaee |","meaning_en":"she taught him cleverness in many ways.","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਬਸਤ੍ਰ ਮਲੀਨ ਉਤਾਰਿ ਭਲੇ ਪਹਿਰਾਇ ਕੈ।","roman":"Basatr maleen utaari bhale pahiraai kai |","meaning_en":"Taking off his dirty clothes and dressing him in good ones,","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਤਹ ਲ੍ਯਾਵਤ ਤਿਹ ਭਈ ਸੁ ਭੇਸ ਬਨਾਇ ਕੈ। ੨੬।","roman":"Ho tah lyaavat tih bhaee su bhes banaai kai | 26 |","meaning_en":"she brought him there, having made him handsomely attired.","page":1841,"meaning_status":"draft"}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":1841,"lines":[{"gurmukhi":"ਮਨ ਭਾਵਤ ਜਬ ਮੀਤ ਤਰੁਨਿ ਤਿਨ ਪਾਇਯੋ।","roman":"Man bhaavat jab meet taruni tin paaiyo |","meaning_en":"When the young woman got the friend her heart desired,","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਤਾ ਕੌ ਗਹਿ ਗਰੇ ਲਗਾਇਯੋ।","roman":"Bhaati bhaati taa kau gahi gare lagaaiyo |","meaning_en":"she took hold of him and held him to her neck in many ways.","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਆਸਨ ਚੁੰਬਨ ਕਰੇ ਹਰਖ ਉਪਜਾਇ ਕੈ।","roman":"Aasan chunban kare harakh upjaai kai |","meaning_en":"She took postures and gave kisses, with joy rising in her,","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਤਵਨ ਸਖੀ ਕੋ ਦਾਰਿਦ ਸਕਲ ਮਿਟਾਇ ਕੈ। ੨੭।","roman":"Ho tavan sakhee ko daarid sakal mitaai kai | 27 |","meaning_en":"having wiped away all the poverty of that companion.","page":1841,"meaning_status":"draft","note":"That is, she rewarded the maid richly."}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":1841,"lines":[{"gurmukhi":"ਦਿਜਿਕ ਦ੍ਰੁਗਾ ਕੀ ਪੂਜਾ ਕਰੀ ਰਿਝਾਇਯੋ।","roman":"Dijik drugaa kee poojaa karee rijhaaiyo |","meaning_en":"A Brahmin worshipped Durga and pleased her,","page":1841,"meaning_status":"draft","note":"ਦਿਜਿਕ: 'a Brahmin' (ਦਿਜ ਇਕ)."},{"gurmukhi":"ਤਾ ਕੈ ਕਰ ਤੇ ਏਕ ਅਮਰ ਫਲ ਪਾਇਯੋ।","roman":"Taa kai kar te ek amar phal paaiyo |","meaning_en":"and from her hand received a fruit of immortality.","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨਿ ਲੈ ਕੈ ਭਰਥਰਿ ਰਾਜਾ ਜੂ ਕੋ ਦਿਯੋ।","roman":"Tini lai kai bharathri raajaa joo ko diyo |","meaning_en":"He took it and gave it to King Bharthari:","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਬ ਲੌ ਪ੍ਰਿਥੀ ਅਕਾਸ ਨ੍ਰਿਪਤ ਤਬ ਲੌ ਜਿਯੋ। ੨੮।","roman":"Ho jab lau prithee akaas nripat tab lau jiyo | 28 |","meaning_en":"'As long as earth and sky last, so long may the king live.'","page":1841,"meaning_status":"draft"}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":1841,"lines":[{"gurmukhi":"ਦੁਰਗ ਦਤ ਫਲ ਅਮਰ ਜਬੈ ਨ੍ਰਿਪ ਕਰ ਪਰਿਯੋ।","roman":"Durag dat phal amar jabai nrip kar pariyo |","meaning_en":"When the immortal fruit given by Durga came into the king's hand,","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਭਾਨ ਮਤੀ ਕੋ ਦੇਉ ਇਹੈ ਚਿਤ ਮੈ ਕਰਿਯੋ।","roman":"Bhaan matee ko deu ihai chit mai kariyo |","meaning_en":"he resolved in his mind, 'I will give it to Bhan Mati.'","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਰਿਯ ਕਿਯ ਮਨਹਿ ਬਿਚਾਰ ਕਿ ਮਿਤ੍ਰਹਿ ਦੀਜੀਯੈ।","roman":"Triy kiy manhi bichaar ki mitrahi deejeeyai |","meaning_en":"The woman thought in her mind, 'Let it be given to my friend;","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਸਦਾ ਤਰੁਨ ਸੋ ਰਹੈ ਕੇਲ ਅਤਿ ਕੀਜੀਯੈ। ੨੯।","roman":"Ho sadaa tarun so rahai kel ati keejeeyai | 29 |","meaning_en":"let him stay young for ever, and let there be much love-play.'","page":1841,"meaning_status":"draft"}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":1841,"lines":[{"gurmukhi":"ਮਨ ਭਾਵੰਤ ਮੀਤ ਜਦਿਨ ਸਖਿ ਪਾਈਯੈ।","roman":"Man bhaavant meet jadin sakhi paaeeyai |","meaning_en":"'On the day, O friend, that one finds the friend one's heart desires,","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਤਨ ਮਨ ਧਨ ਸਭ ਵਾਰਿ ਬਹੁਰੁ ਬਲਿ ਜਾਈਯੈ।","roman":"Tan man dhan sabh vaari bahuru bali jaaeeyai |","meaning_en":"one should offer up body, mind and wealth, and then be a sacrifice to him.","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਮੋ ਮਨ ਲਯੋ ਚੁਰਾਇ ਪ੍ਰੀਤਮਹਿ ਆਜੁ ਸਭ।","roman":"Mo man layo churaai preetamhi aaju sabh |","meaning_en":"My beloved has today stolen my whole heart;","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਰਹੈ ਤਰੁਨ ਚਿਰੁ ਜਿਯੈ ਦਿਯੌ ਫਲ ਤਾਹਿ ਲਭ। ੩੦।","roman":"Ho rahai tarun chiru jiyai diyau phal taahi labh | 30 |","meaning_en":"may he stay young and live long' - and she gave him the fruit that had been got.","page":1841,"meaning_status":"draft","note":"ਦਿਯੌ ਫਲ ਤਾਹਿ ਲਭ: 'gave him the fruit obtained'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1841,"meaning_status":"draft"},{"type":"verse","number":[31],"number_text":"੩੧।","page":1841,"lines":[{"gurmukhi":"ਨ੍ਰਿਪ ਕੋ ਚਿਤ ਰਾਨੀ ਹਰ ਲਯੋ। ਅਬਲਾ ਮਨੁ ਤਾ ਕੈ ਕਰ ਦਯੋ।","roman":"Nrip ko chit raanee har layo | ablaa manu taa kai kar dayo |","meaning_en":"The queen had taken away the king's heart; the woman gave her own heart into that man's hand.","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਵਹੁ ਅਟਕਤ ਬੇਸ੍ਵਾ ਪਰ ਭਯੋ। ਫਲ ਲੈ ਕੈ ਤਾ ਕੇ ਕਰ ਦਯੋ। ੩੧।","roman":"Vahu atkat besvaa par bhayo | phal lai kai taa ke kar dayo | 31 |","meaning_en":"He was caught up with a courtesan; taking the fruit, he gave it into her hand.","page":1841,"meaning_status":"draft","note":"ਬੇਸ੍ਵਾ: a courtesan."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1841,"meaning_status":"draft"},{"type":"verse","number":[32],"number_text":"੩੨।","page":1841,"lines":[{"gurmukhi":"ਰਹੀ ਤਰੁਨਿ ਸੋ ਰੀਝਿ ਅੰਗ ਨ੍ਰਿਪ ਕੇ ਨਿਰਖਿ।","roman":"Rahee taruni so reejhi ang nrip ke nirkhi |","meaning_en":"That young woman was charmed on seeing the limbs of the king;","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਚਾਰੁ ਕੀਏ ਚਖ ਰਹੈ ਸਰੂਪ ਅਮੋਲ ਲਖਿ।","roman":"Chaaru kee'e chakh rahai saroop amol lakhi |","meaning_en":"she kept her lovely eyes on him, seeing his priceless form.","page":1841,"meaning_status":"draft","note":"ਚਾਰੁ ਕੀਏ ਚਖ ਰਹੈ: 'kept her eyes made lovely'; uncertain."},{"gurmukhi":"ਫਲ ਸੋਈ ਲੈ ਹਾਥ ਰੁਚਿਤ ਰੁਚਿ ਸੌ ਦਿਯੋ।","roman":"Phal soee lai haath ruchit ruchi sau diyo |","meaning_en":"Taking that same fruit in her hand, she gave it with eager liking:","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਬ ਲੌ ਪ੍ਰਿਥੀ ਅਕਾਸ ਨ੍ਰਿਪਤਿ ਤਬ ਲੌ ਜਿਯੋ। ੩੨।","roman":"Ho jab lau prithee akaas nripti tab lau jiyo | 32 |","meaning_en":"'As long as earth and sky last, so long may the king live.'","page":1841,"meaning_status":"draft"}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":1841,"lines":[{"gurmukhi":"ਲੈ ਬੇਸ੍ਵਾ ਫਲ ਦਿਯੋ ਨ੍ਰਿਪਤਿ ਕੌ ਆਨਿ ਕੈ।","roman":"Lai besvaa phal diyo nripti kau aani kai |","meaning_en":"The courtesan took the fruit, brought it and gave it to the king;","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਰੂਪ ਹੇਰਿ ਬਸਿ ਭਈ ਪ੍ਰੀਤਿ ਅਤਿ ਠਾਨਿ ਕੈ।","roman":"Roop heri basi bhaee preeti ati thaani kai |","meaning_en":"seeing his beauty she had come under his sway, conceiving great love.","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਲੈ ਰਾਜੈ ਤਿਹ ਹਾਥ ਚਿੰਤ ਚਿਤ ਮੈ ਕਿਯੋ।","roman":"Lai raajai tih haath chint chit mai kiyo |","meaning_en":"The king took it in his hand and reflected in his mind:","page":1841,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਯਹ ਸੋਈ ਦ੍ਰੁਮ ਜਾਹਿ ਜੁ ਮੈ ਤ੍ਰਿਯ ਕੌ ਦਿਯੋ। ੩੩।","roman":"Ho yah soee drum jaahi ju mai triy kau diyo | 33 |","meaning_en":"'This is that very fruit which I gave to my wife.'","page":1841,"meaning_status":"draft","note":"ਦ੍ਰੁਮ: 'tree', here the fruit of the tree; uncertain."}]},{"type":"verse","number":[34],"number_text":"੩੪।","page":1843,"lines":[{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਤਿਹ ਲੀਨੋ ਸੋਧ ਬਨਾਇ ਕੈ।","roman":"Bhaati bhaati tih leeno sodh banaai kai |","meaning_en":"He examined it closely in many ways,","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਤਿਹ ਬੇਸ੍ਵਾ ਕੋ ਪੂਛ੍ਯੋ ਨਿਕਟਿ ਬੁਲਾਇ ਕੈ।","roman":"Tih besvaa ko poochhyo nikti bulaai kai |","meaning_en":"and calling that courtesan near, he asked her:","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਸਾਚ ਕਹੋ ਮੁਹਿ ਯਹ ਫਲ ਤੈ ਕਹ ਤੇ ਲਹਿਯੋ।","roman":"Saach kaho muhi yah phal tai kah te lahiyo |","meaning_en":"'Tell me the truth: from where did you get this fruit?'","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਹਾਥ ਜੋਰਿ ਤਿਨ ਬਚਨ ਨ੍ਰਿਪਤਿ ਸੌ ਯੌ ਕਹਿਯੋ। ੩੪।","roman":"Ho haath jori tin bachan nripti sau yau kahiyo | 34 |","meaning_en":"Folding her hands, she spoke these words to the king:","page":1843,"meaning_status":"draft"}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":1843,"lines":[{"gurmukhi":"ਤੁਮ ਅਪਨੇ ਚਿਤ ਜਿਹ ਰਾਨੀ ਕੇ ਕਰ ਦਿਯੋ।","roman":"Tum apne chit jih raanee ke kar diyo |","meaning_en":"'The queen into whose hand you gave it from your heart -","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਕੌ ਏਕ ਚੰਡਾਰ ਮੋਹਿ ਕਰਿ ਮਨੁ ਲਿਯੋ।","roman":"Taa kau ek chandaar mohi kari manu liyo |","meaning_en":"a chandal charmed her and took her heart.","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਤਵਨ ਨੀਚ ਮੁਹਿ ਊਪਰ ਰਹਿਯੋ ਬਿਕਾਇ ਕੈ।","roman":"Tavan neech muhi oopar rahiyo bikaai kai |","meaning_en":"That low-born man has sold himself to me;","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਤਵ ਤ੍ਰਿਯ ਤਿਹ ਦਿਯ ਤਿਨ ਮੁਹਿ ਦਯੋ ਬਨਾਇ ਕੈ। ੩੫।","roman":"Tav triy tih diy tin muhi dayo banaai kai | 35 |","meaning_en":"your wife gave it to him, and he gave it to me.","page":1843,"meaning_status":"draft"}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":1843,"lines":[{"gurmukhi":"ਮੈ ਲਖਿ ਤੁਮਰੌ ਰੂਪ ਰਹੀ ਉਰਝਾਇ ਕੈ।","roman":"Mai lakhi tumrau roop rahee urjhaai kai |","meaning_en":"Seeing your beauty, I have been caught fast;","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਹਰਅਰਿ ਸਰ ਤਨ ਬਧੀ ਸੁ ਗਈ ਬਿਕਾਇ ਕੈ।","roman":"Hara'ari sar tan badhee su gaee bikaai kai |","meaning_en":"pierced in the body by the arrows of Shiva's foe, I am sold to you.","page":1843,"meaning_status":"draft","note":"ਹਰਅਰਿ: 'the enemy of Har (Shiva)', Kama."},{"gurmukhi":"ਸਦਾ ਤਰਨਿ ਤਾ ਕੋ ਫਲੁ ਹਮ ਤੇ ਲੀਜਿਯੈ।","roman":"Sadaa tarni taa ko phalu ham te leejiyai |","meaning_en":"Take from me this fruit of everlasting youth,","page":1843,"meaning_status":"draft","note":"ਸਦਾ ਤਰਨਿ ਤਾ ਕੋ ਫਲੁ: 'the fruit of being ever young'; uncertain."},{"gurmukhi":"ਹੋ ਕਾਮ ਕੇਲ ਮੁਹਿ ਸਾਥ ਹਰਖ ਸੋ ਕੀਜਿਯੈ। ੩੬।","roman":"Ho kaam kel muhi saath harakh so keejiyai | 36 |","meaning_en":"and make love with me joyfully.","page":1843,"meaning_status":"draft"}]},{"type":"verse","number":[37],"number_text":"੩੭।","page":1843,"lines":[{"gurmukhi":"ਤੁਮ ਤਿਹ ਤ੍ਰਿਯ ਜੋ ਦਯੋ ਫਲ ਅਤਿ ਰੁਚਿ ਮਾਨਿ ਕੈ।","roman":"Tum tih triy jo dayo phal ati ruchi maani kai |","meaning_en":"The fruit that you gave to that woman with great liking,","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਲੈ ਦਿਯੋ ਚੰਡਾਰਹਿ ਅਤਿ ਹਿਤੁ ਠਾਨਿ ਕੈ।","roman":"Tin lai diyo chandaarhi ati hitu thaani kai |","meaning_en":"she took and gave to the chandal with great affection;","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਉਨ ਮੁਹਿ ਮੈ ਤੁਹਿ ਦਿਯੋ ਸੁ ਬਿਰਹਾ ਕੀ ਦਹੀ।","roman":"Un muhi mai tuhi diyo su birhaa kee dahee |","meaning_en":"he gave it to me, and I have given it to you, burned as I am by separation;","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਿਰਖਿ ਤਿਹਾਰੀ ਪ੍ਰਭਾ ਦਿਵਾਨੀ ਹ੍ਵੈ ਰਹੀ। ੩੭।","roman":"Ho nirkhi tihaaree prabhaa divaanee hvai rahee | 37 |","meaning_en":"seeing your radiance I have gone out of my mind.","page":1843,"meaning_status":"draft"}]},{"type":"verse","number":[38],"number_text":"੩੮।","page":1843,"lines":[{"gurmukhi":"ਹੈ ਤਵ ਪ੍ਰਭਾ ਬਿਲੋਕਿ ਰਹੀ ਉਰਝਾਇ ਕੈ।","roman":"Hai tav prabhaa biloki rahee urjhaai kai |","meaning_en":"Seeing your radiance I have been caught fast;","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਗ੍ਰਿਹ ਸਿਗਰੇ ਕੀ ਸੰਗ੍ਯਾ ਦਈ ਭੁਲਾਇ ਕੈ।","roman":"Grih sigre kee sangyaa daee bhulaai kai |","meaning_en":"I have forgotten all awareness of my home.","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਅਮਰ ਅਜਰ ਫਲ ਤੁਮ ਕੌ ਦੀਨੋ ਆਨਿ ਕਰਿ।","roman":"Amar ajar phal tum kau deeno aani kari |","meaning_en":"I have brought and given you the undying, unageing fruit;","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਤਾ ਤੇ ਮਦਨ ਸੰਤਾਪ ਨ੍ਰਿਪਤਿ ਹਮਰੋ ਪ੍ਰਹਰਿ। ੩੮।","roman":"Ho taa te madan santaap nripti hamro prahri | 38 |","meaning_en":"therefore, O king, take away the torment of love that is on me.'","page":1843,"meaning_status":"draft"}]},{"type":"verse","number":[39],"number_text":"੩੯।","page":1843,"lines":[{"gurmukhi":"ਧੰਨ੍ਯ ਧੰਨ੍ਯ ਤਾ ਕੌ ਤਬ ਨ੍ਰਿਪਤਿ ਉਚਾਰਿਯੋ।","roman":"Dhanny dhanny taa kau tab nripti uchaariyo |","meaning_en":"Then the king said to her, 'Blessed, blessed!'","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਸੌ ਤਾ ਕੇ ਸੰਗ ਬਿਹਾਰਿਯੋ।","roman":"Bhaati bhaati sau taa ke sang bihaariyo |","meaning_en":"and took his pleasure with her in many ways.","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਲਪਟਿ ਲਪਟਿ ਬੇਸ੍ਵਾ ਹੂੰ ਗਈ ਬਨਾਇ ਕੈ।","roman":"Lapti lapti besvaa hoon gaee banaai kai |","meaning_en":"The courtesan too clung and clung to him,","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਅਪ੍ਰਮਾਨ ਦੁਤਿ ਹੇਰਿ ਰਹੀ ਉਰਝਾਇ ਕੈ। ੩੯।","roman":"Ho apramaan duti heri rahee urjhaai kai | 39 |","meaning_en":"caught fast at the sight of his measureless radiance.","page":1843,"meaning_status":"draft"}]},{"type":"verse","number":[40],"number_text":"੪੦।","page":1843,"lines":[{"gurmukhi":"ਮਨ ਭਾਵੰਤੋ ਮੀਤ ਜਵਨ ਦਿਨ ਪਾਈਯੈ।","roman":"Man bhaavanto meet javan din paaeeyai |","meaning_en":"On the day that one finds the friend one's heart desires,","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਤਵਨ ਘਰੀ ਕੇ ਪਲ ਪਲ ਬਲਿ ਬਲਿ ਜਾਈਯੈ।","roman":"Tavan gharee ke pal pal bali bali jaaeeyai |","meaning_en":"one should be a sacrifice to every instant of that hour,","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਲਪਟਿ ਲਪਟਿ ਕਰਿ ਤਾ ਸੌ ਅਧਿਕ ਬਿਹਾਰੀਯੈ।","roman":"Lapti lapti kari taa sau adhik bihaareeyai |","meaning_en":"cling and cling to him and take great pleasure with him,","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਤਤਖਿਨ ਦ੍ਰਪ ਕੰਦ੍ਰਪ ਕੋ ਸਕਲ ਨਿਵਾਰੀਯੈ। ੪੦।","roman":"Ho tatkhin drap kandrap ko sakal nivaareeyai | 40 |","meaning_en":"and at once put away all the pride of the god of love.","page":1843,"meaning_status":"draft","note":"ਦ੍ਰਪ ਕੰਦ੍ਰਪ ਕੋ: 'the pride of Kandarp (Kama)'."}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1843,"meaning_status":"draft"},{"type":"verse","number":[41],"number_text":"੪੧।","page":1843,"lines":[{"gurmukhi":"ਬਾਲ ਕੋ ਰੂਪ ਬਿਲੋਕਿ ਕੈ ਲਾਲ ਕਛੂ ਹਸਿ ਕੈ ਅਸ ਬੈਨ ਉਚਾਰੇ।","roman":"Baal ko roop biloki kai laal kachhoo hasi kai as bain uchaare |","meaning_en":"Seeing the beauty of the young woman, the dear one laughed a little and spoke these words:","page":1843,"meaning_status":"draft","note":"ਲਾਲ: 'the dear one', the king."},{"gurmukhi":"ਤੈ ਅਟਕੀ ਸੁਨਿ ਸੁੰਦਰਿ ਮੋ ਪਰ ਐਸੇ ਨ ਸੁੰਦਰ ਅੰਗ ਹਮਾਰੇ।","roman":"Tai atkee suni sundri mo par aise na sundar ang hamaare |","meaning_en":"'Listen, beautiful one: you are caught on me, yet my limbs are not so beautiful.","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਜੀਬੋ ਘਨੋ ਸਿਗਰੋ ਜਗ ਚਾਹਤ ਸੋ ਨ ਰੁਚਿਯੋ ਚਿਤ ਮਾਝਿ ਤਿਹਾਰੇ।","roman":"Jeebo ghano sigro jag chaahat so na ruchiyo chit maajhi tihaare |","meaning_en":"The whole world wishes to live long, but that did not appeal to your heart.","page":1843,"meaning_status":"draft"},{"gurmukhi":"ਆਨਿ ਜਰਾਰਿ ਦਯੋ ਹਮ ਕੌ ਫਲੁ ਦਾਸ ਭਏ ਹਮ ਆਜੁ ਤਿਹਾਰੇ। ੪੧।","roman":"Aani jaraari dayo ham kau phalu daas bhae ham aaju tihaare | 41 |","meaning_en":"You have brought and given me the fruit that defeats old age; today I have become your slave.'","page":1843,"meaning_status":"draft","note":"ਜਰਾਰਿ: 'the enemy of old age'."}]},{"type":"heading","kind":"speaker","name":"ਬੇਸ੍ਵਾ ਵਾਚ","gurmukhi":"ਬੇਸ੍ਵਾ ਵਾਚ","roman":"Besvaa vaach","meaning_en":"The courtesan said:","page":1845,"meaning_status":"draft"},{"type":"verse","number":[42],"number_text":"੪੨।","page":1845,"lines":[{"gurmukhi":"ਨੈਨ ਲਗੇ ਜਬ ਤੇ ਤੁਮ ਸੌ ਤਬ ਤੇ ਤਵ ਹੇਰਿ ਪ੍ਰਭਾ ਬਲਿ ਜਾਊ।","roman":"Nain lage jab te tum sau tab te tav heri prabhaa bali jaaoo |","meaning_en":"'Ever since my eyes met yours, I have been a sacrifice to the sight of your radiance.","page":1845,"meaning_status":"draft"},{"gurmukhi":"ਭੌਨ ਭੰਡਾਰ ਸੁਹੁਾਤ ਨ ਮੋ ਕਹ ਸੋਵਤ ਹੂੰ ਬਿਝ ਕੈ ਬਰਰਾਊ।","roman":"Bhaun bhandaar suhaat na mo kah sovat hoon bijh kai barraaoo |","meaning_en":"House and treasury do not please me; even in sleep I start up and babble.","page":1845,"meaning_status":"draft","note":"ਬਿਝ ਕੈ: 'starting up'; uncertain. ਸੁਹੁਾਤ: printed so."},{"gurmukhi":"ਜੈਤਿਕ ਆਪਨੀ ਆਰਬਲਾ ਸਭ ਮੀਤ ਕੇ ਊਪਰ ਵਾਰਿ ਬਹਾਊ।","roman":"Jaitik aapnee aarablaa sabh meet ke oopar vaari bahaaoo |","meaning_en":"Whatever span of life is mine, I would offer it all over my friend and cast it away.","page":1845,"meaning_status":"draft","note":"ਆਰਬਲਾ: span of life."},{"gurmukhi":"ਕੇਤਿਕ ਬਾਤ ਜਰਾਰਿ ਸੁਨੋ ਫਲ ਪ੍ਰਾਨ ਦੈ ਮੋਲ ਪਿਯਾ ਕਹ ਲ੍ਯਾਊ। ੪੨।","roman":"Ketik baat jaraari suno phal praan dai mol piyaa kah lyaaoo | 42 |","meaning_en":"Listen: what is a fruit that defeats old age? I would buy my beloved at the price of my life.","page":1845,"meaning_status":"draft"}]},{"type":"verse","number":[43],"number_text":"੪੩।","page":1845,"lines":[{"gurmukhi":"ਤੈ ਜੁ ਦਿਯੋ ਤੀਯ ਕੋ ਫਲ ਥੋ ਦਿਜ ਤੇ ਕਰਿ ਕੋਟਿਕੁਪਾਇ ਲੀਯੋ।","roman":"Tai ju diyo teey ko phal tho dij te kari kotikupaai leeyo |","meaning_en":"The fruit that you gave your wife, which was got from the Brahmin by countless efforts,","page":1845,"meaning_status":"draft","note":"ਕੋਟਿਕੁਪਾਇ: 'by crores of means'."},{"gurmukhi":"ਸੋਊ ਲੈ ਕਰ ਜਾਰ ਕੌ ਦੇਤ ਭਈ ਤਿਨ ਰੀਝਿ ਕੈ ਮੋ ਪਰ ਮੋਹਿ ਦੀਯੋ।","roman":"So'oo lai kar jaar kau det bhaee tin reejhi kai mo par mohi deeyo |","meaning_en":"she took and gave to her lover, and he, pleased with me, gave it to me.","page":1845,"meaning_status":"draft"},{"gurmukhi":"ਨ੍ਰਿਪ ਹੌ ਅਟਕੀ ਤਵ ਹੇਰਿ ਪ੍ਰਭਾ ਤਨ ਕੋ ਤਨਿ ਕੈ ਨਹਿ ਤਾਪ ਕੀਯੋ।","roman":"Nrip hau atkee tav heri prabhaa tan ko tani kai nahi taap keeyo |","meaning_en":"O king, I was caught at the sight of your radiance, and did not care in the least for my body's own pain.","page":1845,"meaning_status":"draft","note":"ਤਨ ਕੋ ਤਨਿ ਕੈ ਨਹਿ ਤਾਪ ਕੀਯੋ: sense uncertain; read as 'did not mind my body's suffering even a little'."},{"gurmukhi":"ਤਿਹ ਖਾਹੁ ਹਮੈ ਸੁਖ ਦੇਹ ਦਿਯੋ ਨ੍ਰਿਪ ਰਾਜ ਕਰੋ ਜੁਗ ਚਾਰ ਜੀਯੋ। ੪੩।","roman":"Tih khaahu hamai sukh deh diyo nrip raaj karo jug chaar jeeyo | 43 |","meaning_en":"Eat it, give me the pleasure of your body, O king; rule and live for the four ages.'","page":1845,"meaning_status":"draft","note":"ਸੁਖ ਦੇਹ ਦਿਯੋ: read as 'give bodily pleasure'; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਭਰਥਰਿ ਬਾਚ","gurmukhi":"ਭਰਥਰਿ ਬਾਚ","roman":"Bharathri baach","meaning_en":"Bharthari said:","page":1845,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1845,"meaning_status":"draft"},{"type":"verse","number":[44],"number_text":"੪੪।","page":1845,"lines":[{"gurmukhi":"ਧ੍ਰਿੰਗ ਮੁਹਿ ਕੌ ਮੈ ਜੁ ਫਲੁ ਤ੍ਰਿਯਹਿ ਦੈ ਡਾਰਿਯੌ।","roman":"Dhring muhi kau mai ju phalu triyhi dai daariyau |","meaning_en":"'Shame on me, that I gave the fruit away to my wife.","page":1845,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਧ੍ਰਿਗ ਤਿਹ ਦਿਯੋ ਚੰਡਾਰ ਜੁ ਧ੍ਰਮ ਨ ਬਿਚਾਰਿਯੌ।","roman":"Dhrig tih diyo chandaar ju dhram na bichaariyau |","meaning_en":"Shame on her who gave it to the chandal and did not think of righteousness.","page":1845,"meaning_status":"draft"},{"gurmukhi":"ਧ੍ਰਿਗ ਤਾ ਕੋ ਤਿਨ ਤ੍ਰਿਯ ਰਾਨੀ ਸੀ ਪਾਇ ਕੈ।","roman":"Dhrig taa ko tin triy raanee see paai kai |","meaning_en":"Shame on him who, having gained a woman like the queen,","page":1845,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਦਯੋ ਬੇਸ੍ਵਹਿ ਪਰਮ ਪ੍ਰੀਤਿ ਉਪਜਾਇ ਕੈ। ੪੪।","roman":"Ho dayo besvahi param preeti upjaai kai | 44 |","meaning_en":"gave it to a courtesan, conceiving great love for her.'","page":1845,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1845,"meaning_status":"draft"},{"type":"verse","number":[45],"number_text":"੪੫।","page":1845,"lines":[{"gurmukhi":"ਆਧਿਕ ਆਪੁ ਭਖ੍ਯੋ ਨ੍ਰਿਪ ਲੈ ਫਲ ਆਧਿਕ ਰੂਪਮਤੀ ਕਹ ਦੀਨੋ।","roman":"Aadhik aapu bhakhyo nrip lai phal aadhik roopamtee kah deeno |","meaning_en":"The king took the fruit and ate half himself, and half he gave to Rupmati.","page":1845,"meaning_status":"draft","note":"ਰੂਪਮਤੀ: 'the beautiful one'; taken as the courtesan's name; uncertain."},{"gurmukhi":"ਯਾਰ ਕੈ ਟੂਕ ਹਜਾਰ ਕਰੇ ਗਹਿ ਨਾਰਿ ਭਿਟ੍ਯਾਰ ਤਿਨੈ ਬਧਿ ਕੀਨੋ।","roman":"Yaar kai took hajaar kare gahi naari bhityaar tinai badhi keeno |","meaning_en":"He cut the lover into a thousand pieces, and seizing the wife and the go-between, he killed them.","page":1845,"meaning_status":"draft","note":"ਭਿਟ੍ਯਾਰ: unclear; read as the woman who brought them together (the maid); uncertain."},{"gurmukhi":"ਭੌਨ ਭੰਡਾਰ ਬਿਸਾਰ ਸਭੈ ਕਛੁ ਰਾਮ ਕੋ ਨਾਮੁ ਹ੍ਰਿਦੈ ਦ੍ਰਿੜ ਚੀਨੋ।","roman":"Bhaun bhandaar bisaar sabhai kachhu raam ko naamu hridai drir cheeno |","meaning_en":"Forgetting house, treasury and all else, he fixed the Name of Ram firmly in his heart.","page":1845,"meaning_status":"draft"},{"gurmukhi":"ਜਾਇ ਬਸ੍ਯੋ ਤਬ ਹੀ ਬਨ ਮੈ ਨ੍ਰਿਪ ਭੇਸ ਕੋ ਤ੍ਯਾਗ ਜੁਗੇਸ ਕੋ ਲੀਨੋ। ੪੫।","roman":"Jaai basyo tab hee ban mai nrip bhes ko tyaag juges ko leeno | 45 |","meaning_en":"He went at once and lived in the forest; giving up the dress of a king, he took that of a lord of yogis.","page":1845,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1845,"meaning_status":"draft"},{"type":"verse","number":[46],"number_text":"੪੬।","page":1845,"lines":[{"gurmukhi":"ਬਨ ਭੀਤਰ ਭੇਟਾ ਭਈ ਗੋਰਖ ਸੰਗ ਸੁ ਧਾਰ।","roman":"Ban bheetar bhetaa bhaee gorakh sang su dhaar |","meaning_en":"In the forest he met with Gorakh;","page":1845,"meaning_status":"draft","note":"ਸੁ ਧਾਰ: filler for the rhyme, 'well'; uncertain."},{"gurmukhi":"ਰਾਜ ਤ੍ਯਾਗ ਅੰਮ੍ਰਿਤ ਲਯੋ ਭਰਥਿਰ ਰਾਜ ਕੁਮਾਰ। ੪੬।","roman":"Raaj tyaag anmrit layo bharthir raaj kumaar | 46 |","meaning_en":"giving up his kingdom, the prince Bharthari took the nectar of immortality.","page":1845,"meaning_status":"draft","note":"ਅੰਮ੍ਰਿਤ: nectar; the yogic teaching is meant."}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1845,"meaning_status":"draft"},{"type":"verse","number":[47],"number_text":"੪੭।","page":1845,"lines":[{"gurmukhi":"ਰੋਵਤ ਹੈ ਸੁ ਕਹੂੰ ਪੁਰ ਕੇ ਜਨ ਬੌਰੇ ਸੇ ਡੋਲਤ ਜ੍ਯੋ ਮਤਵਾਰੇ।","roman":"Rovat hai su kahoon pur ke jan baure se dolat jyo matvaare |","meaning_en":"Somewhere the people of the city weep, and wander about like madmen or drunkards;","page":1845,"meaning_status":"draft"},{"gurmukhi":"ਫਾਰਤ ਚੀਰ ਸੁ ਬੀਰ ਗਿਰੇ ਕਹੂੰ ਜੂਝੈ ਹੈ ਖੇਤ ਮਨੋ ਜੁਝਿਯਾਰੇ।","roman":"Phaarat cheer su beer gire kahoon joojhai hai khet mano jujhiyaare |","meaning_en":"somewhere brave men have fallen, tearing their clothes, as if warriors had fallen on the field;","page":1845,"meaning_status":"draft"},{"gurmukhi":"ਰੋਵਤ ਨਾਰ ਅਪਾਰ ਕਹੂੰ ਬਿਸੰਭਾਰਿ ਭਈ ਕਰਿ ਨੈਨਨ ਤਾਰੇ।","roman":"Rovat naar apaar kahoon bisanbhaari bhaee kari nainan taare |","meaning_en":"somewhere countless women weep, and have lost their senses with their eyes fixed and staring:","page":1845,"meaning_status":"draft","note":"ਕਰਿ ਨੈਨਨ ਤਾਰੇ: 'with the pupils of the eyes fixed'; uncertain."},{"gurmukhi":"ਤ੍ਯਾਗ ਕੈ ਰਾਜ ਸਮਾਜ ਸਭੈ ਮਹਾਰਾਜ ਸਖੀ ਬਨ ਆਜੁ ਪਧਾਰੇ। ੪੭।","roman":"Tyaag kai raaj samaaj sabhai mahaaraaj sakhee ban aaju padhaare | 47 |","meaning_en":"'Giving up all his royal state, O friend, the great king has gone to the forest today.'","page":1845,"meaning_status":"draft"}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":1847,"lines":[{"gurmukhi":"ਨਿਜੁ ਨਾਰਿ ਨਿਹਾਰਿ ਕੈ ਭਰਥ ਕੁਮਾਰਿ ਬਿਸਾਰਿ ਸੰਭਾਰਿ ਛਕੀ ਮਨ ਮੈ।","roman":"Niju naari nihaari kai bharath kumaari bisaari sanbhaari chhakee man mai |","meaning_en":"His own wives, on seeing Prince Bharthari, lost all composure and were dazed in mind.","page":1847,"meaning_status":"draft","note":"ਭਰਥ ਕੁਮਾਰਿ: read as 'Prince Bharthari' (ਕੁਮਾਰ); uncertain."},{"gurmukhi":"ਕਹੂੰ ਹਾਰ ਗਿਰੈ ਕਹੂੰ ਬਾਰ ਲਸੈ ਕਛੁ ਨੈਕੁ ਪ੍ਰਭਾ ਨ ਰਹੀ ਤਨ ਮੈ।","roman":"Kahoon haar girai kahoon baar lasai kachhu naiku prabhaa na rahee tan mai |","meaning_en":"Here a necklace falls, there the hair hangs loose; not the least lustre is left in their bodies.","page":1847,"meaning_status":"draft"},{"gurmukhi":"ਝਖ ਕੇਤੁਕ ਬਾਨਨ ਪੀੜਤ ਭੀ ਮਨ ਜਾਇ ਰਹਿਯੋ ਮਨ ਮੋਹਨ ਮੈ।","roman":"Jhakh ketuk baanan peerat bhee man jaai rahiyo man mohan mai |","meaning_en":"They were tormented by the arrows of the fish-bannered god; their minds had gone and stayed with the charmer of their hearts,","page":1847,"meaning_status":"draft","note":"ਝਖ ਕੇਤੁ: Kama, whose banner bears a fish."},{"gurmukhi":"ਮਨੋ ਦੀਪਕ ਭੇਦ ਸੁਨੋ ਸੁਰ ਨਾਦ ਮ੍ਰਿਗੀ ਗਨ ਜਾਨੁ ਬਿਧੀ ਮਨ ਮੈ। ੪੮।","roman":"Mano deepak bhed suno sur naad mrigee gan jaanu bidhee man mai | 48 |","meaning_en":"as if a herd of does, hearing the notes of the Dipak raga, had been pierced in the heart.","page":1847,"meaning_status":"draft","note":"ਦੀਪਕ ਭੇਦ: 'a mode of Dipak', the raga; the line is compressed; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1847,"meaning_status":"draft"},{"type":"verse","number":[49],"number_text":"੪੯।","page":1847,"lines":[{"gurmukhi":"ਅਨਿਕ ਜਤਨ ਕਰਿ ਕਰਿ ਤ੍ਰਿਯਾ ਹਾਰਤ ਭਈ ਅਨੇਕ।","roman":"Anik jatan kari kari triyaa haarat bhaee anek |","meaning_en":"The many women wore themselves out with countless efforts;","page":1847,"meaning_status":"draft"},{"gurmukhi":"ਬਨ ਹੀ ਕੌ ਨ੍ਰਿਪ ਜਾਤ ਭਯੋ ਮਾਨਿਯੋ ਬਚਨ ਨ ਏਕ। ੪੯।","roman":"Ban hee kau nrip jaat bhayo maaniyo bachan na ek | 49 |","meaning_en":"the king went away to the forest and did not heed a single word.","page":1847,"meaning_status":"draft"}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":1847,"lines":[{"gurmukhi":"ਜਬ ਰਾਜਾ ਬਨ ਮੈ ਗਏ ਗੋਰਖ ਗੁਰੂ ਬੁਲਾਇ।","roman":"Jab raajaa ban mai gae gorakh guroo bulaai |","meaning_en":"When the king had gone into the forest, Guru Gorakh called him,","page":1847,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਰਿ ਭਾਤਿ ਸਿਛ੍ਯਾ ਦਈ ਤਾਹਿ ਸਿਖ੍ਯ ਠਹਰਾਇ। ੫੦।","roman":"Bahuri bhaati sichhyaa daee taahi sikhy thahraai | 50 |","meaning_en":"and making him his disciple, gave him teaching in many ways.","page":1847,"meaning_status":"draft"}]},{"type":"heading","kind":"speaker","name":"ਭਰਥਰੀ ਬਾਚ","gurmukhi":"ਭਰਥਰੀ ਬਾਚ","roman":"Bharathree baach","meaning_en":"Bharthari said:","page":1847,"meaning_status":"draft"},{"type":"verse","number":[51],"number_text":"੫੧।","page":1847,"lines":[{"gurmukhi":"ਕਵਨ ਮਰੈ ਮਾਰੈ ਕਵਨ ਕਹਤ ਸੁਨਤ ਕਹ ਕੋਇ।","roman":"Kavan marai maarai kavan kahat sunat kah koi |","meaning_en":"'Who dies and who kills? Who is it that speaks and hears?","page":1847,"meaning_status":"draft"},{"gurmukhi":"ਕੋ ਰੋਵੈ ਕਵਨੈ ਹਸੈ ਕਵਨ ਜਰਾ ਜਿਤ ਹੋਇ। ੫੧।","roman":"Ko rovai kavnai hasai kavan jaraa jit hoi | 51 |","meaning_en":"Who weeps and who laughs? Who is overcome by old age?'","page":1847,"meaning_status":"draft","note":"ਕਵਨ ਜਰਾ ਜਿਤ ਹੋਇ: 'who becomes conquered by age' (or 'conquers age'); uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1847,"meaning_status":"draft"},{"type":"verse","number":[52],"number_text":"੫੨।","page":1847,"lines":[{"gurmukhi":"ਹਸਿ ਗੋਰਖ ਇਮਿ ਬਚਨ ਉਚਾਰੇ। ਸੁਨਹੁ ਭਰਥ ਹਰਿ ਰਾਜ ਹਮਾਰੇ।","roman":"Hasi gorakh imi bachan uchaare | sunhu bharath hari raaj hamaare |","meaning_en":"Laughing, Gorakh spoke these words: 'Listen, Bharthari, my king.","page":1847,"meaning_status":"draft"},{"gurmukhi":"ਸਤਿ ਝੂਠ ਮੂਓ ਹੰਕਾਰਾ। ਕਬਹੂ ਮਰਤ ਨ ਬੋਲਨਹਾਰਾ। ੫੨।","roman":"Sati jhooth moo'o hankaaraa | kabhoo marat na bolanhaaraa | 52 |","meaning_en":"Truth, falsehood and pride die; the one who speaks never dies.","page":1847,"meaning_status":"draft","note":"ਬੋਲਨਹਾਰਾ: 'the speaker', the soul within. ਸਤਿ ਝੂਠ: 'truth and falsehood'; could also be read 'truly, falsehood and pride die'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1847,"meaning_status":"draft"},{"type":"verse","number":[53],"number_text":"੫੩।","page":1847,"lines":[{"gurmukhi":"ਕਾਲ ਮਰੈ ਕਾਯਾ ਮਰੈ ਕਾਲੈ ਕਰਤ ਉਚਾਰ।","roman":"Kaal marai kaayaa marai kaalai karat uchaar |","meaning_en":"It is Kal that dies, the body that dies, and Kal that utters speech;","page":1847,"meaning_status":"draft","note":"ਕਾਲ: Time/Death, here the power working in all; left as 'Kal'."},{"gurmukhi":"ਜੀਭੈ ਗੁਨ ਬਖ੍ਯਾਨ ਹੀ ਸ੍ਰਵਨਨ ਸੁਨਤ ਸੁਧਾਰ। ੫੩।","roman":"Jeebhai gun bakhyaan hee sravnan sunat sudhaar | 53 |","meaning_en":"as the tongue it tells of qualities, and as the ears it listens well.","page":1847,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1847,"meaning_status":"draft"},{"type":"verse","number":[54],"number_text":"੫੪।","page":1847,"lines":[{"gurmukhi":"ਕਾਲ ਨੈਨ ਹ੍ਵੈ ਸਭਨ ਨਿਹਰਈ। ਕਾਲ ਬਕਤ੍ਰ ਹ੍ਵੈ ਬਾਕ ਉਚਰਈ।","roman":"Kaal nain hvai sabhan nihraee | kaal bakatr hvai baak uchraee |","meaning_en":"Kal, becoming the eyes, looks upon all; Kal, becoming the mouth, utters speech.","page":1847,"meaning_status":"draft"},{"gurmukhi":"ਕਾਲ ਮਰਤ ਕਾਲ ਹੀ ਮਾਰੈ। ਭੂਲਾ ਲੋਗ ਭਰਮ ਬੀਚਾਰੈ। ੫੪।","roman":"Kaal marat kaal hee maarai | bhoolaa log bharam beechaarai | 54 |","meaning_en":"Kal dies and Kal alone kills; deluded people think otherwise in their error.","page":1847,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1847,"meaning_status":"draft"},{"type":"verse","number":[55],"number_text":"੫੫।","page":1847,"lines":[{"gurmukhi":"ਕਾਲ ਹਸਤ ਕਾਲੈ ਰੋਵਤ ਕਰਤ ਜਰਾ ਜਿਤ ਹੋਇ।","roman":"Kaal hasat kaalai rovat karat jaraa jit hoi |","meaning_en":"Kal laughs and Kal weeps, and makes old age the victor;","page":1847,"meaning_status":"draft","note":"ਕਰਤ ਜਰਾ ਜਿਤ ਹੋਇ: uncertain, as in verse 51."},{"gurmukhi":"ਕਾਲ ਪਾਇ ਉਪਜਤ ਸਭੈ ਕਾਲ ਪਾਇ ਬਧ ਹੋਇ। ੫੫।","roman":"Kaal paai upjat sabhai kaal paai badh hoi | 55 |","meaning_en":"by Kal all are born, and by Kal they are slain.","page":1847,"meaning_status":"draft","note":"ਕਾਲ ਪਾਇ: 'on getting their time' or 'through Kal'."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1847,"meaning_status":"draft"},{"type":"verse","number":[56],"number_text":"੫੬।","page":1847,"lines":[{"gurmukhi":"ਕਾਲੈ ਮਰਤ ਕਾਲ ਹੀ ਮਾਰੈ। ਭ੍ਰਮਿ ਭ੍ਰਮਿ ਪਿੰਡ ਅਵਾਰਾ ਪਾਰੈ।","roman":"Kaalai marat kaal hee maarai | bhrami bhrami pind avaaraa paarai |","meaning_en":"Kal dies and Kal alone kills; wandering and wandering, it sets the body adrift.","page":1847,"meaning_status":"draft","note":"ਪਿੰਡ ਅਵਾਰਾ ਪਾਰੈ: read as 'makes the body a wanderer'; uncertain."},{"gurmukhi":"ਕਾਮ ਕ੍ਰੋਧ ਮੂਓ ਹੰਕਾਰਾ। ਏਕ ਨ ਮਰਿਯੋ ਸੁ ਬੋਲਣਹਾਰਾ। ੫੬।","roman":"Kaam krodh moo'o hankaaraa | ek na mariyo su bolanhaaraa | 56 |","meaning_en":"Lust, anger and pride have died; one alone has not died, the one who speaks.","page":1847,"meaning_status":"draft"}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":1849,"lines":[{"gurmukhi":"ਆਸਾ ਕਰਤ ਸਕਲ ਜਗ ਮਰਈ। ਕੌਨ ਪੁਰਖੁ ਆਸਾ ਪਰਹਰਈ।","roman":"Aasaa karat sakal jag maraee | kaun purkhu aasaa parahraee |","meaning_en":"The whole world dies while still hoping; what man gives up hope?","page":1849,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਨਰ ਕੋਊ ਆਸ ਕੌ ਤ੍ਯਾਗੈ। ਸੋ ਹਰਿ ਕੇ ਪਾਇਨ ਸੌ ਲਾਗੈ। ੫੭।","roman":"Jo nar ko'oo aas kau tyaagai | so hari ke paain sau laagai | 57 |","meaning_en":"Whoever gives up hope is joined to the feet of Hari.","page":1849,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1849,"meaning_status":"draft"},{"type":"verse","number":[58],"number_text":"੫੮।","page":1849,"lines":[{"gurmukhi":"ਆਸਾ ਕੀ ਆਸਾ ਪੁਰਖ ਜੋ ਕੋਊ ਤਜਤ ਬਨਾਇ।","roman":"Aasaa kee aasaa purakh jo ko'oo tajat banaai |","meaning_en":"The man who truly gives up even the hope of hope","page":1849,"meaning_status":"draft"},{"gurmukhi":"ਪਾਪ ਪੁੰਨ੍ਯ ਸਰ ਤਰਿ ਤੁਰਤ ਪਰਮ ਪੁਰੀ ਕਹ ਜਾਇ। ੫੮।","roman":"Paap punny sar tari turat param puree kah jaai | 58 |","meaning_en":"at once swims across the lake of sin and merit and goes to the supreme city.'","page":1849,"meaning_status":"draft"}]},{"type":"verse","number":[59],"number_text":"੫੯।","page":1849,"lines":[{"gurmukhi":"ਜ੍ਯੋ ਸਮੁੰਦਹਿ ਗੰਗਾ ਮਿਲਤ ਸਹੰਸ ਧਾਰ ਕੈ ਸਾਜ।","roman":"Jyo samundhi gangaa milat sahans dhaar kai saaj |","meaning_en":"As the Ganga meets the ocean after forming a thousand streams,","page":1849,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਯੋ ਗੋਰਖ ਰਿਖਿਰਾਜ ਸਿਯੋ ਆਜੁ ਮਿਲ੍ਯੋ ਨ੍ਰਿਪ ਰਾਜ। ੫੯।","roman":"Tyo gorakh rikhiraaj siyo aaju milyo nrip raaj | 59 |","meaning_en":"so today the king of kings met with Gorakh, the king of sages.","page":1849,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1849,"meaning_status":"draft"},{"type":"verse","number":[60],"number_text":"੬੦।","page":1849,"lines":[{"gurmukhi":"ਯਾਤੇ ਮੈ ਬਿਸਥਾਰ ਨ ਕਰੌ। ਗ੍ਰੰਥ ਬਢਨ ਤੇ ਅਤਿ ਚਿਤ ਡਰੌ।","roman":"Yaate mai bisthaar na karau | granth badhan te ati chit darau |","meaning_en":"For this reason I do not go into detail; I greatly fear in my mind the swelling of the book.","page":1849,"meaning_status":"draft","note":"The poet speaks."},{"gurmukhi":"ਤਾ ਤੇ ਕਥਾ ਨ ਅਧਿਕ ਬਢਾਈ। ਭੂਲ ਪਰੀ ਤਹ ਲੇਹੁ ਬਨਾਈ। ੬੦।","roman":"Taa te kathaa na adhik badhaaee | bhool paree tah lehu banaaee | 60 |","meaning_en":"Therefore I have not made the tale much longer; where there is a mistake, set it right.","page":1849,"meaning_status":"draft"}]},{"type":"verse","number":[61],"number_text":"੬੧।","page":1849,"lines":[{"gurmukhi":"ਗੋਰਖ ਸੋ ਗੋਸਟਿ ਜਬ ਭਈ। ਰਾਜਾ ਕੀ ਦੁਰਮਤਿ ਸਭ ਗਈ।","roman":"Gorakh so gosti jab bhaee | raajaa kee duramti sabh gaee |","meaning_en":"When the discourse with Gorakh had taken place, all the king's wrong thinking went away.","page":1849,"meaning_status":"draft"},{"gurmukhi":"ਸੀਖਤ ਗ੍ਯਾਨ ਭਲੀ ਬਿਧਿ ਭਯੋ। ਜਲ ਹ੍ਵੈ ਜ੍ਯੋ ਜਲ ਮੈ ਮਿਲਿ ਗਯੋ। ੬੧।","roman":"Seekhat gyaan bhalee bidhi bhayo | jal hvai jyo jal mai mili gayo | 61 |","meaning_en":"He learned wisdom in a good way, and merged like water into water.","page":1849,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1849,"meaning_status":"draft"},{"type":"verse","number":[62],"number_text":"੬੨।","page":1849,"lines":[{"gurmukhi":"ਏਕ ਮੂੰਡ ਭਰਥਰਿ ਘ੍ਰਿਤ ਚੁਅਤ ਨਿਹਾਰਿਯੋ।","roman":"Ek moond bharathri ghrit chuat nihaariyo |","meaning_en":"Bharthari saw a head dripping with ghee;","page":1849,"meaning_status":"draft","note":"ਮੂੰਡ: 'head'; perhaps a skull or a pot-shaped vessel; the story behind the verse is not given; uncertain."},{"gurmukhi":"ਹਸਿ ਹਸਿ ਤਾ ਸੋ ਬਚਨ ਇਹ ਭਾਤਿ ਉਚਾਰਿਯੋ।","roman":"Hasi hasi taa so bachan ih bhaati uchaariyo |","meaning_en":"laughing and laughing, he spoke to it in this way:","page":1849,"meaning_status":"draft"},{"gurmukhi":"ਜਿਨ ਕੋ ਲਗੇ ਕਟਾਛ ਰਾਜ ਤੇ ਖੋਵਹੀ।","roman":"Jin ko lage kataachh raaj te khovhee |","meaning_en":"'Those who are struck by a woman's sidelong glance lose their kingdoms;","page":1849,"meaning_status":"draft","note":"'a woman's' is understood from ਕਟਾਛ, the sidelong glance."},{"gurmukhi":"ਹੋ ਤੁਹਿ ਕਰ ਲਾਗੇ ਤੈ ਕ੍ਯੋ ਮੂਢ ਨ ਰੋਵਹੀ। ੬੨।","roman":"Ho tuhi kar laage tai kyo moodh na rovhee | 62 |","meaning_en":"you have been touched by her hand; why then, fool, do you not weep?'","page":1849,"meaning_status":"draft","note":"ਤੁਹਿ ਕਰ ਲਾਗੇ: 'the hand has touched you'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1849,"meaning_status":"draft"},{"type":"verse","number":[63],"number_text":"੬੩।","page":1849,"lines":[{"gurmukhi":"ਬੀਤਤ ਬਰਖ ਬਹੁਤ ਜਬ ਭਏ। ਭਰਥਰਿ ਦੇਸ ਆਪਨੇ ਗਏ।","roman":"Beetat barakh bahut jab bhae | bharathri des aapne gae |","meaning_en":"When many years had gone by, Bharthari went to his own country.","page":1849,"meaning_status":"draft"},{"gurmukhi":"ਚੀਨਤ ਏਕ ਚੰਚਲਾ ਭਈ। ਨਿਕਟ ਰਾਨਿਯਨ ਕੇ ਚਲਿ ਗਈ। ੬੩।","roman":"Cheenat ek chanchlaa bhaee | nikat raaniyan ke chali gaee | 63 |","meaning_en":"A woman recognised him, and went to the queens.","page":1849,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1849,"meaning_status":"draft"},{"type":"verse","number":[64],"number_text":"੬੪।","page":1849,"lines":[{"gurmukhi":"ਸੁਨਿ ਰਾਨਿਯਨ ਐਸੋ ਬਚਨ ਰਾਜਾ ਲਿਯੋ ਬੁਲਾਇ।","roman":"Suni raaniyan aiso bachan raajaa liyo bulaai |","meaning_en":"Hearing such news, the queens had the king called;","page":1849,"meaning_status":"draft"},{"gurmukhi":"ਭਾਤਿ ਭਾਤਿ ਰੋਦਨ ਕਰਤ ਰਹੀ ਚਰਨ ਲਪਟਾਇ। ੬੪।","roman":"Bhaati bhaati rodan karat rahee charan laptaai | 64 |","meaning_en":"weeping in many ways, they clung to his feet.","page":1849,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"Sortha.","page":1849,"meaning_status":"draft"},{"type":"verse","number":[65],"number_text":"੬੫।","page":1849,"lines":[{"gurmukhi":"ਮਾਸਾ ਰਹਿਯੋ ਨ ਮਾਸ ਰਕਤ ਰੰਚ ਤਨ ਨ ਰਹਿਯੋ।","roman":"Maasaa rahiyo na maas rakat ranch tan na rahiyo |","meaning_en":"'Not a masha of flesh is left, not a trace of blood is left in the body;","page":1849,"meaning_status":"draft","note":"ਮਾਸਾ: a masha, a very small weight."},{"gurmukhi":"ਸ੍ਵਾਸ ਨ ਉਡ੍ਯੋ ਉਸਾਸ ਆਸ ਤਿਹਾਰੈ ਮਿਲਨ ਕੀ। ੬੫।","roman":"Svaas na udyo usaas aas tihaarai milan kee | 65 |","meaning_en":"the breath has not flown off with our sighs, only in the hope of meeting you.","page":1849,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1849,"meaning_status":"draft"},{"type":"verse","number":[66],"number_text":"੬੬।","page":1849,"lines":[{"gurmukhi":"ਜੋਗ ਕੀਯੋ ਪੂਰਨ ਭਯੋ ਨ੍ਰਿਪ ਬਰ। ਅਬ ਤੁਮ ਰਾਜ ਕਰੋ ਸੁਖ ਸੌ ਘਰ।","roman":"Jog keeyo pooran bhayo nrip bar | ab tum raaj karo sukh sau ghar |","meaning_en":"You have practised yoga and become perfect, excellent king; now rule at home in comfort.","page":1849,"meaning_status":"draft"},{"gurmukhi":"ਜੌ ਸਭਹਿਨ ਹਮ ਪ੍ਰਥਮ ਸੰਘਾਰੋ। ਤਾ ਪਾਛੇ ਬਨ ਓਰ ਸਿਧਾਰੋ। ੬੬।","roman":"Jau sabhhin ham pratham sanghaaro | taa paachhe ban or sidhaaro | 66 |","meaning_en":"Or else first kill all of us, and after that set out for the forest.'","page":1849,"meaning_status":"draft","note":"ਜੌ: 'if'; read as 'or else'; uncertain."}]},{"type":"heading","kind":"speaker","name":"ਭਰਥਰਿ ਬਾਚ","gurmukhi":"ਭਰਥਰਿ ਬਾਚ","roman":"Bharathri baach","meaning_en":"Bharthari said:","page":1851,"meaning_status":"draft"},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1851,"meaning_status":"draft"},{"type":"verse","number":[67],"number_text":"੬੭।","page":1851,"lines":[{"gurmukhi":"ਜੇ ਰਾਨੀ ਜੋਬਨ ਭਰੀ ਅਧਿਕ ਤਬੈ ਗਰਬਾਹਿ।","roman":"Je raanee joban bharee adhik tabai garbaahi |","meaning_en":"'The queens who then were full of youth and very proud","page":1851,"meaning_status":"draft"},{"gurmukhi":"ਤੇ ਅਬ ਰੂਪ ਰਹਿਤ ਭਈ ਰਹਿਯੋ ਗਰਬ ਕਛੁ ਨਾਹਿ। ੬੭।","roman":"Te ab roop rahit bhaee rahiyo garab kachhu naahi | 67 |","meaning_en":"have now become bereft of beauty; no pride at all remains.","page":1851,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1851,"meaning_status":"draft"},{"type":"verse","number":[68],"number_text":"੬੮।","page":1851,"lines":[{"gurmukhi":"ਅਬਲਾ ਹੁਤੀ ਤਰੁਨਿ ਤੇ ਭਈ। ਤਰੁਨਿ ਜੁ ਹੁਤੀ ਬ੍ਰਿਧ ਹ੍ਵੈ ਗਈ।","roman":"Ablaa hutee taruni te bhaee | taruni ju hutee bridh hvai gaee |","meaning_en":"She who was a girl became a young woman; she who was a young woman became old.","page":1851,"meaning_status":"draft","note":"ਅਬਲਾ: 'woman'; read here as 'girl' (ਬਾਲਾ) for the contrast; uncertain."},{"gurmukhi":"ਬਿਰਧਨਿ ਤੇ ਕੋਊ ਲਹੀ ਨ ਜਾਵੈ। ਚਿਤ ਕੌ ਇਹੈ ਅਸਚਰਜ ਆਵੈ। ੬੮।","roman":"Biradhni te ko'oo lahee na jaavai | chit kau ihai asachraj aavai | 68 |","meaning_en":"Of those who were old, not one is to be found; this is the wonder that comes to my mind.","page":1851,"meaning_status":"draft"}]},{"type":"verse","number":[69],"number_text":"੬੯।","page":1851,"lines":[{"gurmukhi":"ਜੇ ਰਾਨੀ ਜੋਬਨ ਕੀ ਭਰੀ। ਤੇ ਅਬ ਭਈ ਜਰਾ ਕੀ ਧਰੀ।","roman":"Je raanee joban kee bharee | te ab bhaee jaraa kee dharee |","meaning_en":"The queens who were full of youth have now been seized by old age.","page":1851,"meaning_status":"draft"},{"gurmukhi":"ਜੇ ਅਬਲਾ ਸੁੰਦਰ ਗਰਬਾਹੀ। ਤਿਨ ਕੋ ਰਹਿਯੋ ਗਰਬ ਕਛੁ ਨਾਹੀ। ੬੯।","roman":"Je ablaa sundar garbaahee | tin ko rahiyo garab kachhu naahee | 69 |","meaning_en":"The beautiful women who were proud have no pride at all left.","page":1851,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1851,"meaning_status":"draft"},{"type":"verse","number":[70],"number_text":"੭੦।","page":1851,"lines":[{"gurmukhi":"ਜੇ ਮਨ ਮੈ ਗਰਬਤ ਤਬੈ ਅਧਿਕ ਚੰਚਲਾ ਨਾਰਿ।","roman":"Je man mai garbat tabai adhik chanchlaa naari |","meaning_en":"The restless women who then were very proud in their minds","page":1851,"meaning_status":"draft"},{"gurmukhi":"ਤੇ ਅਬ ਜੀਤਿ ਜਰਾ ਲਈ ਸਕਤ ਨ ਦੇਹ ਸੰਭਾਰਿ। ੭੦।","roman":"Te ab jeeti jaraa laee sakat na deh sanbhaari | 70 |","meaning_en":"have now been conquered by old age; they cannot hold up their bodies.","page":1851,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1851,"meaning_status":"draft"},{"type":"verse","number":[71],"number_text":"੭੧।","page":1851,"lines":[{"gurmukhi":"ਜੇ ਜੇ ਤ੍ਰਿਯਾ ਤਬੈ ਗਰਬਾਹੀ। ਤਿਨ ਕੇ ਰਹਿਯੋ ਗਰਬ ਕਛੁ ਨਾਹੀ।","roman":"Je je triyaa tabai garbaahee | tin ke rahiyo garab kachhu naahee |","meaning_en":"Each and every woman who then was proud has no pride at all left.","page":1851,"meaning_status":"draft"},{"gurmukhi":"ਤਰੁਨੀ ਹੁਤੀ ਬਿਰਧ ਤੇ ਭਈ। ਠੌਰੈ ਠੌਰ ਔਰ ਹ੍ਵੈ ਗਈ। ੭੧।","roman":"Tarunee hutee biradh te bhaee | thaurai thaur aur hvai gaee | 71 |","meaning_en":"Those who were young became old; in every part they have become other than they were.","page":1851,"meaning_status":"draft"}]},{"type":"verse","number":[72],"number_text":"੭੨।","page":1851,"lines":[{"gurmukhi":"ਕੇਸਨ ਪ੍ਰਭਾ ਜਾਤ ਨਹਿ ਕਹੀ। ਜਾਨੁਕ ਜਟਨ ਜਾਨਵੀ ਬਹੀ।","roman":"Kesan prabhaa jaat nahi kahee | jaanuk jatan jaanvee bahee |","meaning_en":"The radiance of your hair cannot be told; it is as if the Ganga flowed through matted locks,","page":1851,"meaning_status":"draft","note":"ਜਾਨਵੀ: Jahnavi, the Ganga, flowing white through Shiva's locks."},{"gurmukhi":"ਕੈਧੋ ਸਕਲ ਦੁਗਧ ਸੌ ਧੋਏ। ਤਾ ਤੇ ਸੇਤ ਬਰਨ ਕਚ ਹੋਏ। ੭੨।","roman":"Kaidho sakal dugadh sau dhoe | taa te set baran kach hoe | 72 |","meaning_en":"or as if all of it had been washed in milk, and so the hair has turned white in colour.","page":1851,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1851,"meaning_status":"draft"},{"type":"verse","number":[73],"number_text":"੭੩।","page":1851,"lines":[{"gurmukhi":"ਮੁਕਤਨ ਹੀਰਨ ਕੇ ਬਹੁਤ ਇਨ ਪਰ ਕੀਏ ਸਿੰਗਾਰ।","roman":"Muktan heeran ke bahut in par kee'e singaar |","meaning_en":"Many adornments of pearls and diamonds were put on these;","page":1851,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਤੇ ਤਿਨ ਕੀ ਛਬਿ ਭਏ ਤਰੁਨਿ ਤਿਹਾਰੇ ਬਾਰ। ੭੩।","roman":"Taa te tin kee chhabi bhae taruni tihaare baar | 73 |","meaning_en":"therefore, young woman, your hair has taken on their lustre.","page":1851,"meaning_status":"draft"}]},{"type":"verse","number":[74],"number_text":"੭੪।","page":1851,"lines":[{"gurmukhi":"ਜੋ ਤਬ ਅਤਿ ਸੋਭਿਤ ਹੁਤੇ ਤਰੁਨਿ ਤਿਹਾਰੇ ਕੇਸ।","roman":"Jo tab ati sobhit hute taruni tihaare kes |","meaning_en":"Your hair, young woman, which then was so very beautiful,","page":1851,"meaning_status":"draft"},{"gurmukhi":"ਨੀਲ ਮਨੀ ਕੀ ਛਬਿ ਹੁਤੇ ਭਏ ਰੁਕਮ ਕੇ ਭੇਸ। ੭੪।","roman":"Neel manee kee chhabi hute bhae rukam ke bhes | 74 |","meaning_en":"which had the lustre of sapphire, has taken on the look of silver.","page":1851,"meaning_status":"draft","note":"ਰੁਕਮ: gold or silver; silver here."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1851,"meaning_status":"draft"},{"type":"verse","number":[75],"number_text":"੭੫।","page":1851,"lines":[{"gurmukhi":"ਕੈਧੋ ਸਕਲ ਪੁਹਪ ਗੁਹਿ ਡਾਰੇ। ਤਾ ਤੇ ਕਚ ਸਿਤ ਭਏ ਤਿਹਾਰੇ।","roman":"Kaidho sakal puhap guhi daare | taa te kach sit bhae tihaare |","meaning_en":"Or perhaps all the flowers were strung into it, and so your hair became white;","page":1851,"meaning_status":"draft"},{"gurmukhi":"ਸਸਿ ਕੀ ਜੌਨਿ ਅਧਿਕਧੌ ਪਰੀ। ਤਾ ਤੇ ਸਕਲ ਸ੍ਯਾਮਤਾ ਹਰੀ। ੭੫।","roman":"Sasi kee jauni adhikdhau paree | taa te sakal syaamtaa haree | 75 |","meaning_en":"or the light of the moon fell on it too strongly, and so took all its blackness away.'","page":1851,"meaning_status":"draft","note":"ਅਧਿਕਧੌ: 'much, or perhaps'."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1853,"meaning_status":"draft"},{"type":"verse","number":[76],"number_text":"੭੬।","page":1853,"lines":[{"gurmukhi":"ਇਕ ਰਾਨੀ ਤਬ ਕਹਿਯੋ ਨ੍ਰਿਪਹਿ ਸਮਝਾਇ ਕੈ।","roman":"Ik raanee tab kahiyo nriphi samjhaai kai |","meaning_en":"Then one queen spoke, reasoning with the king:","page":1853,"meaning_status":"draft"},{"gurmukhi":"ਮੁਹਿ ਗੋਰਖ ਕਹਿ ਗਏ ਸੁਪਨ ਮੈ ਆਇ ਕੈ।","roman":"Muhi gorakh kahi gae supan mai aai kai |","meaning_en":"'Gorakh came to me in a dream and told me:","page":1853,"meaning_status":"draft"},{"gurmukhi":"ਜਬ ਲੌ ਤ੍ਰਿਯ ਏ ਜਿਯਤ ਰਾਜ ਤਬ ਲੌ ਕਰੌ।","roman":"Jab lau triy e jiyat raaj tab lau karau |","meaning_en":"\"As long as these women live, so long rule the kingdom;","page":1853,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਬ ਏ ਸਭ ਮਰਿ ਜੈ ਹੈ ਤਬ ਪਗ ਮਗ ਧਰੋ। ੭੬।","roman":"Ho jab e sabh mari jai hai tab pag mag dharo | 76 |","meaning_en":"when they have all died, then set your foot upon the road.\"'","page":1853,"meaning_status":"draft"}]},{"type":"verse","number":[77],"number_text":"੭੭।","page":1853,"lines":[{"gurmukhi":"ਸੁਨਿ ਰਨਿਯਨ ਕੇ ਬਚਨ ਨ੍ਰਿਪਹਿ ਕਰੁਣਾ ਭਈ।","roman":"Suni raniyan ke bachan nriphi karunaa bhaee |","meaning_en":"Hearing the words of the queens, the king felt compassion;","page":1853,"meaning_status":"draft"},{"gurmukhi":"ਤਿਨ ਕੈ ਭੀਤਰ ਬੁਧ ਕਛੁਕ ਅਪੁਨੀ ਦਈ।","roman":"Tin kai bheetar budh kachhuk apunee daee |","meaning_en":"he put something of his own understanding into them.","page":1853,"meaning_status":"draft"},{"gurmukhi":"ਜੋ ਕਛੁ ਪਿੰਗੁਲ ਕਹਿਯੋ ਮਾਨ ਸੋਈ ਲਿਯੋ।","roman":"Jo kachhu pingul kahiyo maan soee liyo |","meaning_en":"Whatever Pingula said, that he accepted;","page":1853,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਰਾਜ ਜੋਗ ਘਰ ਬੈਠ ਦੋਊ ਅਪਨੇ ਕਿਯੋ। ੭੭।","roman":"Ho raaj jog ghar baith do'oo apne kiyo | 77 |","meaning_en":"sitting at home, he made both kingship and yoga his own.","page":1853,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1853,"meaning_status":"draft"},{"type":"verse","number":[78,1],"number_text":"੭੮। ੧।","page":1853,"lines":[{"gurmukhi":"ਮਾਨਿ ਰਾਨਿਯਨ ਕੋ ਬਚਨ ਰਾਜ ਕਰਿਯੋ ਸੁਖ ਮਾਨਿ।","roman":"Maani raaniyan ko bachan raaj kariyo sukh maani |","meaning_en":"Heeding the word of the queens, he ruled the kingdom in comfort;","page":1853,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਰਿ ਪਿੰਗੁਲ ਕੇ ਮਰੇ ਬਨ ਕੌ ਕਿਯੋ ਪਯਾਨ। ੭੮। ੧।","roman":"Bahuri pingul ke mare ban kau kiyo payaan | 78 | 1 |","meaning_en":"then, when Pingula died, he set out for the forest.","page":1853,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਦੋਇ ਸੌ ਨੌ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade doi sau nau charitr samaaptam","meaning_en":"Thus ends the two hundred and ninth charitra of the Charitropakhyan, of the wiles of women, in the dialogue of the minister and the king; complete.","page":1853,"meaning_status":"draft"},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੨੦੯। ੪੦੧੨। ਅਫਜੂੰ।","roman":"Satu subham satu | 209 | 4012 | aphjoon |","meaning_en":"True, auspicious, true. 209. 4012. It continues.","page":1853,"meaning_status":"draft","note":"ਸਤੁ ਸੁਭਮ ਸਤੁ: a closing benediction; read as 'may it be auspicious' (ਸਤੁ as 'may it be'); ਸਤੁ could also be 'true'; uncertain. The numbers are the charitra number and the running verse count. ਅਫਜੂੰ: Persian afzun, 'more', taken as 'more follows'; uncertain."}],"page":1853,"number":[209,4012]}});
